# --------------------------------------------------------------------------
# Metric explanation table for the User Guide (bilingual).
# DataSource contract: "Observed" = computed from the raw readings only;
# "Interpolated" = computed on the patient-specific linear-interpolated
# timeline; "Derived" = filled in during data preparation.
# --------------------------------------------------------------------------
METRIC_DEFS <- data.frame(
  Metric = c("PP", "MAP",
             "max_value", "min_value", "Delta", "mean", "SD", "CV", "ARV", "VIM",
             "Load", "Sa", "Sc", "AUC", "Ts1_total", "Ts2_total", "Ts3_total",
             "TTR", "TOTR", "TUTR", "hyper_Burden", "hypo_Burden",
             "cumulative_Load", "Se", "Sf"),
  DataSource = c("Derived", "Derived",
                 rep("Observed", 9),
                 rep("Interpolated", 14)),
  Formula = c(
    "PP = SBP - DBP (only where missing)",
    "MAP = DBP + (SBP - DBP) / 3 (only where missing)",
    "max(x)",
    "min(x)",
    "max(x) - min(x)",
    "mean = sum(x) / n",
    "SD = sqrt( sum((x - mean)^2) / (n - 1) )  (sample SD)",
    "CV = SD / |mean| * 100",
    "ARV = mean( |x[i+1] - x[i]| )  (time-ordered readings)",
    "VIM = SD / mean^beta * k  (cohort: beta = slope of ln(SD)~ln(mean), k = cohort_mean^beta;  fixed: beta = 1, k = reference mean)",
    "Load = count(x > upper) / n_valid * 100  (24h segmented: day & night counts above their OWN limits are summed)",
    "Area above the upper limit (linear interpolation, exact threshold crossings)",
    "Area below the lower limit (linear interpolation, exact threshold crossings)",
    "Total area under the curve (trapezoid rule on the interpolated timeline)",
    "Time above the upper limit (exact crossing times)",
    "Time within the target range (exact crossing times)",
    "Time below the lower limit (exact crossing times)",
    "TTR = Ts2 / (Ts1 + Ts2 + Ts3) * 100",
    "TOTR = Ts1 / (Ts1 + Ts2 + Ts3) * 100",
    "TUTR = Ts3 / (Ts1 + Ts2 + Ts3) * 100",
    "hyper_Burden = (Sa / (Sa + Se)) * (Ts1 / total_time) * 100",
    "hypo_Burden = (Sc / Sf) * (Ts3 / total_time) * 100",
    "cumulative_Load = Sa / Sd * 100",
    "Se = Ts1 * upper_limit",
    "Sf = Ts3 * lower_limit"
  ),
  EN = c(
    "Pulse pressure; derived only where missing, device-measured values are kept",
    "Mean arterial pressure; derived only where missing, device-measured values are kept",
    "Maximum value (raw readings only)",
    "Minimum value (raw readings only)",
    "Range (max - min)",
    "Mean (raw readings only)",
    "Standard deviation, sample (raw readings only)",
    "Coefficient of variation",
    "Average real variability of successive readings",
    "Variability independent of the mean (cohort or fixed standardization)",
    "Share of raw readings above the upper limit",
    "Area above the upper limit (intermediate)",
    "Area below the lower limit (intermediate)",
    "Total area under the curve",
    "Total time above the upper limit (min)",
    "Total time within range (min)",
    "Total time below the lower limit (min)",
    "Time in target range; higher is better",
    "Time over target range; lower is better",
    "Time under target range; lower is better",
    "Hyper burden combining time and amplitude; lower is better",
    "Hypo burden combining time and amplitude; lower is better",
    "Cumulative load",
    "Rectangular area for hyper burden (intermediate)",
    "Rectangular area for hypo burden (intermediate)"
  ),
  CN = c(
    "脉压；仅缺失时按 SBP-DBP 补算，导入的设备实测值保留",
    "平均动脉压；仅缺失时按公式补算，导入的设备实测值保留",
    "最大值（仅原始读数）",
    "最小值（仅原始读数）",
    "波动范围（最大值-最小值）",
    "平均值（仅原始读数）",
    "标准差（样本，仅原始读数）",
    "变异系数",
    "相邻读数的平均真实变异",
    "均值独立变异（队列或固定标化）",
    "超过上限的原始读数占比",
    "高于上限的面积（中间量）",
    "低于下限的面积（中间量）",
    "曲线下总面积",
    "高于上限的总时间（分钟）",
    "目标范围内总时间（分钟）",
    "低于下限的总时间（分钟）",
    "目标范围内时间比例，越高越好",
    "高于目标范围时间比例，越低越好",
    "低于目标范围时间比例，越低越好",
    "高值负担（综合时间与幅度），越低越好",
    "低值负担（综合时间与幅度），越低越好",
    "累积负荷",
    "高值时间矩形面积（中间量）",
    "低值时间矩形面积（中间量）"
  ),
  stringsAsFactors = FALSE
)

# =============================================================================
# Bilingual helpers, column aliases and raw Mobil-O-Graph 24h PWA preprocessing
# =============================================================================

# Language of the currently rendered page; kept in sync by the server so that
# chart/table helpers can localize without a `lang` argument at every call site.
APP_LANG <- "en"
chart_tr <- function(key) tr(APP_LANG, key)

# Alias table for automatic column detection.
# Targets are the canonical post-preprocessing column names. Source columns
# may use unit suffixes, separators or Chinese punctuation - normalization
# removes all whitespace/punctuation and lower-cases ASCII, so
# "SBP (mmHg)", "SBP_MMHG", "sbpmmHg" and "收缩压(mmHg)" all match.
ABPM_ALIASES <- list(
  MASKID = c("MASKID", "PATIENTID", "PATIENT_ID", "PATIENT", "SUBJECT",
             "SUBJECTID", "SUBJECT_ID", "SUBJID", "SUBJ", "ID", "PID",
             "PTID", "PATIENT_NO", "PATIENTNO", "MEDICAL_RECORD_NO",
             "患者", "受试者", "病人编号", "患者编号", "受试者编号", "编号", "病历号",
             # Device exports label the running-index / study-number column
             # "Number" or "No." depending on the firmware version. These sit
             # last on purpose: alias lookups run in list order, so a file that
             # also carries a real MASKID/PATIENT_ID column always maps the ID
             # to that column instead of to a leading counter.
             "NUMBER", "NO", "NUM", "NR", "序号"),
  Time   = c("TIME", "TIME_STR", "TIMESTAMP", "DATE_TIME", "DATETIME",
             "DT", "READING_TIME", "MEASURE_TIME", "HHMM",
             "时间", "日期时间", "测量时间", "时间点"),
  SBP    = c("SBP", "SYS", "SYSTOLIC", "SBPSYS", "SYSTOLE",
             "SYSTOLICBP", "SYSTOLIC_BLOOD_PRESSURE",
             "SBP_MMHG", "SBP (mmHg)", "收缩压", "收缩压(mmHg)"),
  DBP    = c("DBP", "DIA", "DIASTOLIC", "DBPDIA", "DIASTOLE",
             "DIASTOLICBP", "DIASTOLIC_BLOOD_PRESSURE",
             "DBP_MMHG", "DBP (mmHg)", "舒张压", "舒张压(mmHg)"),
  HR     = c("HR", "PULSE", "PULSE_RATE", "HEART_RATE", "HEARTRATE",
             "HEARTBEAT", "PR", "HR_BPM", "HR (bpm)",
             "心率", "心率(次/分)", "脉搏"),
  PP     = c("PP", "PULSE_PRESSURE", "PULSEPRESSURE", "PPP",
             "PP_MMHG", "PP (mmHg)", "脉压", "脉压差", "脉压(mmHg)"),
  MAP    = c("MAP", "MEAN_ARTERIAL_PRESSURE", "MEANBP", "MBP",
             "MAP_MMHG", "MAP (mmHg)", "平均动脉压", "平均动脉压(mmHg)", "平均压"),
  GLU    = c("GLU", "GLUCOSE", "BG", "BLOOD_GLUCOSE", "SENSOR_GLUCOSE",
             "GLU_MMOL", "GLU (mmol/L)", "血糖", "血糖值", "血糖值(mmol/L)",
             "血糖(mmol/L)", "葡萄糖")
)

# Normalize a column name for alias matching: strip all whitespace and
# punctuation, then lower-case pure-ASCII names; CJK names keep their
# characters (punctuation removed, so 收缩压(mmHg) -> 收缩压mmHg).
# ASCII detection uses a perl regex because [\x20-\x7E] ranges behave
# unreliably across locales (e.g. GBK).
norm_col <- function(x) {
  x <- trimws(as.character(x))
  x <- gsub("[[:space:][:punct:]]", "", x)
  is_ascii <- !grepl("[^\\x00-\\x7F]", x, perl = TRUE)
  x[is_ascii] <- tolower(x[is_ascii])
  x
}
ABPM_ALIASES_NORM <- lapply(ABPM_ALIASES, function(v) vapply(v, norm_col, character(1)))

# Detect which source columns match the canonical targets. Each source column
# is assigned to at most one target, in priority order MASKID > Time > metrics.
# Every target key is always present in the returned list (NA when unmapped) so
# callers can safely test `is.na(mapping$GLU)` even when GLU is absent - a NULL
# element here used to crash the mapping panel with "missing value where
# TRUE/FALSE needed".
alias_lookup <- function(col_names) {
  col_names <- as.character(col_names)
  normed <- vapply(col_names, norm_col, character(1))
  taken <- character(0)
  mapping <- list(MASKID = NA_character_, Time = NA_character_, SBP = NA_character_,
                  DBP = NA_character_, HR = NA_character_, PP = NA_character_,
                  MAP = NA_character_, GLU = NA_character_)
  for (target in names(ABPM_ALIASES_NORM)) {
    # Walk each alias list in order so the most canonical name wins: a file
    # that carries both "MASKID" and a leading "No." counter still maps the ID
    # to "MASKID" instead of to whichever column happens to come first.
    for (alias in ABPM_ALIASES_NORM[[target]]) {
      hit <- which(normed == alias & !(col_names %in% taken))
      if (length(hit) > 0) {
        mapping[[target]] <- col_names[hit[1]]
        taken <- c(taken, col_names[hit[1]])
        break
      }
    }
  }
  mapping
}

# --------------------------------------------------------------------------
# Raw Mobil-O-Graph 24h PWA export parsing and conversion.
# Layout: single sheet, key/value metadata rows on top, header row containing
# an index column ("Number"/"No."/...) plus "Systole", then the measurement
# table.
# --------------------------------------------------------------------------

# Some device .xls exports carry a damaged OLE2 stream that readxl's libxls
# refuses to open ("libxls error: Unable to open file"), although Python's
# xlrd reads them fine. This bridge exports the first sheet to a temp CSV via
# Python/xlrd, which the parser then treats like a plain cell matrix.
XLS_BRIDGE_PY <- paste(c(
  "import sys, csv",
  "import xlrd",
  "path_in, path_out = sys.argv[1], sys.argv[2]",
  "wb = xlrd.open_workbook(path_in, on_demand=True)",
  "sh = wb.sheet_by_index(0)",
  "def fmt(cell):",
  "    if cell.ctype == xlrd.XL_CELL_DATE:",
  "        dt = xlrd.xldate_as_datetime(cell.value, wb.datemode)",
  "        return dt.strftime('%Y-%m-%d %H:%M:%S.%f')",
  "    if cell.ctype == xlrd.XL_CELL_NUMBER:",
  "        v = cell.value",
  "        return int(v) if v == int(v) else v",
  "    return cell.value",
  "with open(path_out, 'w', newline='', encoding='utf-8-sig') as f:",
  "    w = csv.writer(f)",
  "    for r in range(sh.nrows):",
  "        w.writerow([fmt(sh.cell(r, c)) for c in range(sh.ncols)])"
), collapse = "\n")

find_python <- function() {
  for (cmd in c("python", "python3", "py")) {
    p <- Sys.which(cmd)
    if (nzchar(p) && file.exists(p)) return(p)
  }
  base_dirs <- c(
    list.files("C:/", pattern = "^Python\\d+$", full.names = TRUE),
    list.files(file.path(Sys.getenv("LOCALAPPDATA"), "Programs", "Python"),
               full.names = TRUE, include.dirs = TRUE),
    list.files("C:/Program Files", pattern = "^Python\\d+$", full.names = TRUE)
  )
  for (d in base_dirs) {
    exe <- file.path(d, "python.exe")
    if (file.exists(exe)) return(exe)
  }
  NULL
}

# Character matrix of the first sheet: readxl first, Python/xlrd bridge as a
# fallback for damaged legacy .xls files.
read_sheet_cell_matrix <- function(path) {
  res <- tryCatch({
    sheets <- readxl::excel_sheets(path)
    raw <- suppressWarnings(readxl::read_excel(path, sheet = sheets[1], col_names = FALSE))
    as.matrix(raw)
  }, error = function(e) e)
  if (!inherits(res, "error")) return(res)

  if (!grepl("\\.xls$", tolower(path))) stop(res)

  py <- find_python()
  if (is.null(py)) {
    stop("Unable to read this file: readxl failed and no Python/xlrd fallback is available. ",
         "无法读取该文件：readxl 失败且没有可用的 Python/xlrd 回退方案。")
  }
  csv_out <- tempfile(fileext = ".csv")
  script <- tempfile(fileext = ".py")
  ok <- tryCatch({
    writeLines(XLS_BRIDGE_PY, script, useBytes = TRUE)
    status <- system2(py, c(shQuote(script), shQuote(path), shQuote(csv_out)),
                      stdout = FALSE, stderr = FALSE)
    isTRUE(status == 0) && file.exists(csv_out) && file.info(csv_out)$size > 0
  }, error = function(e) FALSE)
  if (!isTRUE(ok)) {
    unlink(c(script, csv_out))
    stop("Unable to read this file: readxl failed and the Python/xlrd bridge failed. ",
         "无法读取该文件：readxl 与 Python/xlrd 回退均失败。")
  }
  df <- tryCatch(
    suppressWarnings(read.csv(csv_out, header = FALSE, stringsAsFactors = FALSE,
                              na.strings = character(0), colClasses = "character",
                              fileEncoding = "UTF-8-BOM")),
    error = function(e) NULL)
  unlink(c(script, csv_out))
  if (is.null(df)) stop("Unable to parse the fallback CSV produced by the Python bridge.")
  as.matrix(df)
}

# Header cells of the data block differ between firmware/localisation versions:
# the running-index column is "Number" in most exports but "No." / "No" / "Nr."
# in others (and "序号"/"编号" in localized ones). Normalize case, whitespace
# and trailing punctuation before comparing so the header row is found either
# way. Only the measurement columns are read downstream, so the index column
# keeps whatever label the export happens to use.
header_cell_key <- function(x) {
  x <- trimws(as.character(x))
  x <- gsub("[[:space:][:punct:]]", "", x)
  is_ascii <- !grepl("[^\\x00-\\x7F]", x, perl = TRUE)
  x[is_ascii] <- tolower(x[is_ascii])
  x
}
ABPM_INDEX_LABELS <- c("number", "no", "nr", "num", "index", "序号", "编号")
ABPM_SYSTOLE_LABELS <- c("systole", "sbp", "systolic", "收缩压")

read_abpm_pwa_xls <- function(path) {
  if (!file.exists(path)) stop("File not found: ", path)
  vals_mat <- read_sheet_cell_matrix(path)
  sheet_name <- tryCatch(readxl::excel_sheets(path)[1], error = function(e) NA_character_)
  header_row <- NA_integer_
  for (i in seq_len(nrow(vals_mat))) {
    keys <- header_cell_key(vals_mat[i, ])
    has_systole <- any(keys %in% ABPM_SYSTOLE_LABELS, na.rm = TRUE)
    # Primary match: index column + Systole. Fallback: Systole + Date, so an
    # export whose index column uses an unknown label still parses.
    if (has_systole && (any(keys %in% ABPM_INDEX_LABELS, na.rm = TRUE) ||
                        any(keys %in% c("date", "datetime", "日期"), na.rm = TRUE))) {
      header_row <- i
      break
    }
  }
  if (is.na(header_row)) {
    stop("Could not locate the data header row ('Number'/'No.' + 'Systole') in: ", basename(path))
  }
  meta <- list()
  if (header_row > 1) {
    for (i in seq_len(header_row - 1)) {
      k <- as.character(vals_mat[i, 1])
      v <- as.character(vals_mat[i, 2])
      if (!is.na(k) && nzchar(trimws(k))) {
        meta[[trimws(k)]] <- if (is.na(v)) NA_character_ else trimws(v)
      }
    }
  }
  header <- as.character(vals_mat[header_row, ])
  data_raw <- as.data.frame(
    vals_mat[seq.int(header_row + 1L, nrow(vals_mat)), , drop = FALSE],
    stringsAsFactors = FALSE
  )
  names(data_raw) <- header
  data_raw[data_raw == ""] <- NA
  list(sheet = sheet_name, meta = meta, header_row = header_row, data = data_raw)
}

parse_abpm_datetime <- function(x) {
  if (inherits(x, "POSIXct")) return(as.POSIXct(x))
  if (inherits(x, "Date")) return(as.POSIXct(x))
  xc <- as.character(x)
  out <- rep(as.POSIXct(NA, tz = "UTC"), length(xc))
  for (fmt in c("%Y-%m-%d %H:%M:%OS", "%Y-%m-%d %H:%M:%S",
                "%d.%m.%Y %H:%M:%S", "%d.%m.%Y %H:%M", "%Y-%m-%d")) {
    nas <- is.na(out) & !is.na(xc)
    if (!any(nas)) break
    parsed <- suppressWarnings(as.POSIXct(xc[nas], format = fmt, tz = "UTC"))
    out[nas] <- parsed
  }
  out
}

# Convert one raw export into the canonical long table
# MASKID, Time, SBP, DBP, HR, PP, MAP  (Time = HHMM+XD, day offset relative to
# the first VALID reading). Device-measured pPP/MAP are kept; failed readings
# (SBP/DBP/HR <= 0 or missing) are dropped and counted.
# MASKID priority: maskid_override (user input) > metadata ID > the original
# file name (file_label, e.g. the uploaded file's name) > local path stem.
xls_to_abpm_long <- function(path, maskid_override = NULL, file_label = NULL) {
  parsed <- read_abpm_pwa_xls(path)
  d <- parsed$data
  need <- c("Date", "Systole", "Diastole", "Hr")
  missing_cols <- setdiff(need, names(d))
  if (length(missing_cols) > 0) {
    stop("Missing required columns (", paste(missing_cols, collapse = ", "),
         ") in: ", basename(path))
  }
  d$`_dt` <- parse_abpm_datetime(d$Date)
  d$SBP <- suppressWarnings(as.numeric(as.character(d$Systole)))
  d$DBP <- suppressWarnings(as.numeric(as.character(d$Diastole)))
  d$HR  <- suppressWarnings(as.numeric(as.character(d$Hr)))
  d$PP  <- if ("pPP" %in% names(d)) suppressWarnings(as.numeric(as.character(d$pPP))) else NA_real_
  d$MAP <- if ("MAP" %in% names(d)) suppressWarnings(as.numeric(as.character(d$MAP))) else NA_real_

  n_total <- nrow(d)
  bad_time <- is.na(d$`_dt`)
  valid <- !bad_time &
    is.finite(d$SBP) & is.finite(d$DBP) & is.finite(d$HR) &
    d$SBP > 0 & d$DBP > 0 & d$HR > 0
  n_bad_time <- sum(bad_time)
  n_zero <- sum(!bad_time & !valid)

  v <- d[valid, , drop = FALSE]
  v <- v[order(v$`_dt`), , drop = FALSE]
  out <- data.frame(
    MASKID = rep(NA_character_, nrow(v)),
    Time = rep(NA_character_, nrow(v)),
    SBP = v$SBP, DBP = v$DBP, HR = v$HR, PP = v$PP, MAP = v$MAP,
    stringsAsFactors = FALSE
  )
  auto_id <- NA_character_
  if (nrow(v) > 0) {
    first_date <- as.Date(v$`_dt`[1])
    day_off <- as.integer(as.Date(v$`_dt`) - first_date)
    out$Time <- sprintf("%02d%02d+%dD",
                        as.integer(format(v$`_dt`, "%H")),
                        as.integer(format(v$`_dt`, "%M")),
                        day_off)
    auto_id <- if (!is.null(maskid_override) && !is.na(maskid_override) &&
                   nzchar(trimws(maskid_override))) {
      trimws(maskid_override)
    } else {
      meta_id <- parsed$meta[["ID"]]
      if (!is.null(meta_id) && !is.na(meta_id) && nzchar(trimws(meta_id))) {
        trimws(meta_id)
      } else {
        label <- file_label %||% basename(path)
        tools::file_path_sans_ext(label)
      }
    }
    out$MASKID <- auto_id
  }
  list(
    data = out,
    meta = parsed$meta,
    sheet = parsed$sheet,
    n_total = n_total,
    n_valid = nrow(v),
    n_dropped_zero = n_zero,
    n_dropped_bad_time = n_bad_time,
    first_valid = if (nrow(v) > 0) format(v$`_dt`[1], "%Y-%m-%d %H:%M:%S") else NA_character_,
    last_valid = if (nrow(v) > 0) format(v$`_dt`[nrow(v)], "%Y-%m-%d %H:%M:%S") else NA_character_,
    auto_maskid = auto_id
  )
}

# Unit label for display purposes (charts, summaries, cards)
metric_unit <- function(metric) {
  switch(toupper(as.character(metric)),
         SBP = "mmHg", DBP = "mmHg", PP = "mmHg", MAP = "mmHg",
         HR = "bpm", GLU = "mmol/L",
         "")
}

sanitize_filename <- function(x) {
  x <- gsub("[^A-Za-z0-9_.-]", "_", x)
  x <- gsub("_+", "_", x)
  x <- sub("^_|_$", "", x)
  if (!nzchar(x)) "abpm_export"
  x
}

# Write the selected CSV export items into one zip archive at `file`.
# Returns TRUE when at least one table was packed. The `zip` package is
# preferred: it bundles libzip, so no external zip executable is needed and no
# setwd() is involved (utils::zip() needs zip.exe on Windows, which a plain R
# install does not ship - it then fails with '"zip"' not found and writes no
# archive). utils::zip() is kept only as a fallback for installations without
# the package.
write_export_zip <- function(items, file) {
  tmpd <- tempfile("abpm_export_")
  dir.create(tmpd, recursive = TRUE)
  paths <- character(0)
  for (item in items) {
    for (nm in names(item$csv)) {
      p <- file.path(tmpd, paste0(sanitize_filename(nm), ".csv"))
      con <- base::file(p, open = "wb")
      writeBin(as.raw(c(0xEF, 0xBB, 0xBF)), con)   # UTF-8 BOM so Excel reads CJK
      write.table(item$csv[[nm]], con, sep = ",", row.names = FALSE,
                  col.names = TRUE, qmethod = "double", na = "")
      close(con)
      paths <- c(paths, p)
    }
  }
  if (length(paths) == 0) {
    unlink(tmpd, recursive = TRUE)
    return(FALSE)
  }
  if (isTRUE(has_zip)) {
    zip::zip(zipfile = file, files = basename(paths), root = tmpd,
             include_directories = FALSE)
  } else {
    old_wd <- setwd(tmpd)
    on.exit(setwd(old_wd), add = TRUE)
    utils::zip(zipfile = normalizePath(file, mustWork = FALSE), files = basename(paths))
  }
  TRUE
}

# --------------------------------------------------------------------------
# Glucose (CGM) raw export parsing.
# Typical layout: one sheet whose header row contains the glucose column name
# (血糖值/GLU/GLUCOSE) and a time column name (采集时间/TIME/DATE), plus
# metadata cells such as 机构名称：... 姓名：... 设备名称：... in the same
# row. Data rows: glucose value (mmol/L) and a full date-time. Readings may
# be in descending order and may span many days (+0D..+15D).
# MASKID priority: override > device serial (设备名称) > file label > path.
# --------------------------------------------------------------------------
glu_find_header_row <- function(vals_mat) {
  for (i in seq_len(nrow(vals_mat))) {
    vals <- as.character(vals_mat[i, ])
    has_glu <- any(grepl("GLU|GLUCOSE|血糖值|血糖", vals, ignore.case = TRUE))
    has_time <- any(grepl("时间|TIME|DATE", vals, ignore.case = TRUE))
    if (has_glu && has_time) return(i)
  }
  NA_integer_
}

glu_parse_datetime <- function(x) {
  if (inherits(x, "POSIXct")) return(as.POSIXct(x))
  xc <- as.character(x)
  out <- rep(as.POSIXct(NA, tz = "UTC"), length(xc))
  for (fmt in c("%Y-%m-%d %H:%M:%OS", "%Y-%m-%d %H:%M:%S",
                "%Y/%m/%d %H:%M:%S", "%Y/%m/%d %H:%M", "%Y-%m-%d")) {
    nas <- is.na(out) & !is.na(xc)
    if (!any(nas)) break
    parsed <- suppressWarnings(as.POSIXct(xc[nas], format = fmt, tz = "UTC"))
    out[nas] <- parsed
  }
  out
}

# Convert a glucose cell matrix (or raw CSV text) into the canonical long
# table MASKID,Time,GLU. Returns the same structure as xls_to_abpm_long.
glu_raw_to_long <- function(path = NULL, text = NULL,
                            maskid_override = NULL, file_label = NULL) {
  if (!is.null(path) && file.exists(path)) {
    vals_mat <- read_sheet_cell_matrix(path)
  } else if (!is.null(text) && nzchar(text)) {
    df <- suppressWarnings(read.csv(text = text, header = FALSE,
                                    stringsAsFactors = FALSE,
                                    na.strings = character(0),
                                    colClasses = "character"))
    vals_mat <- as.matrix(df)
  } else {
    stop("No glucose source provided (need a file path or CSV text).")
  }

  header_row <- glu_find_header_row(vals_mat)
  if (is.na(header_row)) {
    stop("Could not locate the glucose header row (GLU/血糖值 + time column).")
  }
  header <- as.character(vals_mat[header_row, ])
  meta_row <- as.character(vals_mat[header_row, ])
  device_serial <- NA_character_
  for (cell in meta_row) {
    if (!is.na(cell) && grepl("设备名称", cell)) {
      device_serial <- trimws(sub("^.*设备名称[:：]", "", cell))
    }
  }

  glu_col <- which(grepl("GLU|GLUCOSE|血糖值|血糖|葡萄糖", header, ignore.case = TRUE))
  time_col <- which(grepl("采集时间|时间|^TIME$|^DATE$|^DT$", header, ignore.case = TRUE))
  if (length(glu_col) == 0 || length(time_col) == 0) {
    stop("Glucose export must contain a glucose column and a time column.")
  }
  glu_col <- glu_col[1]
  time_col <- time_col[1]

  data_raw <- as.data.frame(
    vals_mat[seq.int(header_row + 1L, nrow(vals_mat)), , drop = FALSE],
    stringsAsFactors = FALSE
  )
  data_raw[data_raw == ""] <- NA

  n_total <- nrow(data_raw)
  d_glu <- suppressWarnings(as.numeric(as.character(data_raw[[glu_col]])))
  d_dt <- glu_parse_datetime(data_raw[[time_col]])
  valid <- is.finite(d_glu) & !is.na(d_dt)
  n_invalid <- sum(!valid)

  v_glu <- d_glu[valid]
  v_dt <- d_dt[valid]
  ord <- order(v_dt)
  v_glu <- v_glu[ord]
  v_dt <- v_dt[ord]

  out <- data.frame(MASKID = rep(NA_character_, length(v_glu)),
                    Time = rep(NA_character_, length(v_glu)),
                    GLU = v_glu, stringsAsFactors = FALSE)
  auto_id <- NA_character_
  if (length(v_glu) > 0) {
    first_date <- as.Date(v_dt[1])
    day_off <- as.integer(as.Date(v_dt) - first_date)
    out$Time <- sprintf("%02d%02d+%dD",
                        as.integer(format(v_dt, "%H")),
                        as.integer(format(v_dt, "%M")),
                        day_off)
    auto_id <- if (!is.null(maskid_override) && !is.na(maskid_override) &&
                   nzchar(trimws(maskid_override))) {
      trimws(maskid_override)
    } else if (!is.na(device_serial) && nzchar(device_serial)) {
      device_serial
    } else {
      label <- file_label %||% if (!is.null(path)) basename(path) else "glucose_sample"
      tools::file_path_sans_ext(label)
    }
    out$MASKID <- auto_id
  }
  list(
    data = out,
    meta = list(device_serial = device_serial),
    sheet = NA_character_,
    n_total = n_total,
    n_valid = length(v_glu),
    n_dropped_zero = 0,
    n_dropped_bad_time = n_invalid,
    first_valid = if (length(v_glu) > 0) format(v_dt[1], "%Y-%m-%d %H:%M:%S") else NA_character_,
    last_valid = if (length(v_glu) > 0) format(v_dt[length(v_dt)], "%Y-%m-%d %H:%M:%S") else NA_character_,
    auto_maskid = auto_id
  )
}

# --- 3. UI Definition (bilingual; built by build_ui(lang, settings)) ---
# The page is re-rendered on language switch; input values are restored from
# the `settings` snapshot so no settings are lost.

build_guide_ui <- function(lang) {
  tr2 <- function(key) tr(lang, key)
  steps <- tr(lang, "guide")
  step_blocks <- lapply(seq_along(steps), function(i) {
    tagList(
      h5(tags$strong(paste0(i, ". ", steps[[i]]$title))),
      tags$ul(lapply(steps[[i]]$items, tags$li)),
      br()
    )
  })
  faq_items <- lapply(tr(lang, "faq"), function(f) tags$li(f))
  tagList(
    div(class = "panel panel-default",
        div(class = "panel-heading", style = "background-color: #f5f5f5;",
            h4(icon("book-reader"), tr2("guide_title"), style = "text-align: center; margin: 5px 0;")),
        div(class = "panel-body", style = "font-size: 0.95em;",
            p(tags$em(tr2("guide_intro"))),
            do.call(tagList, step_blocks),
            h5(tags$strong(icon("question"), " ", tr2("faq_title"))),
            tags$ul(faq_items)
        )),
    div(style = "max-height: 420px; overflow-y: auto;",
        h5(tags$strong(icon("tag"), " ", tr2("field_defs_title"), " / ", tr("en", "field_defs_title"))),
        DTOutput("guide_metric_defs_table"))
  )
}

build_author_panel <- function(lang) {
  tr2 <- function(key) tr(lang, key)
  div(class = "panel panel-info", style = "margin-top: 20px;",
      div(class = "panel-heading", style = "text-align: center;",
          h5(icon("user-md"), tr2("about_author"), style = "margin: 5px 0;")),
      div(class = "panel-body", style = "text-align: center; font-size: 0.95em;",
          p(strong(tr2("about_name"))),
          p(tr2("about_affil")),
          p(style = "color: #666;", tr2("app_version")),
          p(tr2("about_contact"), " ", a("morethanlee@163.com", href = "mailto:morethanlee@163.com")),
          hr(),
          p(strong(icon("copyright"), " ", tr2("footer_copyright")))
      ))
}

build_ui <- function(lang, settings) {
  tr2 <- function(key) tr(lang, key)
  s <- function(id, default) {
    v <- settings[[id]]
    if (is.null(v)) default else v
  }
  time_row <- function(id_h, id_m, label, def_h, def_m) {
    tagList(
      tags$label(label),
      fluidRow(
        column(5, style = "padding-right:1px;",
               numericInput(id_h, NULL, value = s(id_h, def_h), min = 0, max = 23, step = 1)),
        column(2, style = "padding-left:1px; padding-right:1px; text-align: center; line-height: 34px;",
               tags$strong(":")),
        column(5, style = "padding-left:1px;",
               numericInput(id_m, NULL, value = s(id_m, def_m), min = 0, max = 59, step = 1))
      )
    )
  }
  target_tab <- function(period) {
    m <- function(metric, def_l, def_u) {
      fluidRow(
        column(6, numericInput(paste0(tolower(metric), "_", period, "_lower"),
                               paste0(metric, " ", tr2("lower")),
                               value = s(paste0(tolower(metric), "_", period, "_lower"), def_l))),
        column(6, numericInput(paste0(tolower(metric), "_", period, "_upper"),
                               paste0(metric, " ", tr2("upper")),
                               value = s(paste0(tolower(metric), "_", period, "_upper"), def_u)))
      )
    }
    if (period == "day") {
      tagList(m("SBP", 90, 120), m("DBP", 55, 70), m("HR", 60, 100),
              m("PP", NA, NA), m("MAP", NA, NA))
    } else if (period == "night") {
      tagList(m("SBP", 90, 110), m("DBP", 55, 60), m("HR", 50, 90),
              m("PP", NA, NA), m("MAP", NA, NA))
    } else {
      tagList(m("SBP", 90, 115), m("DBP", 55, 65), m("HR", 55, 95),
              m("PP", NA, NA), m("MAP", NA, NA))
    }
  }

  sidebar <- sidebarPanel(
    width = 3,

    h4(icon("database"), tr2("data_source_title")),
    radioButtons("domain", tr2("domain_label"),
                 choiceNames = list(tr2("domain_bp"), tr2("domain_glu")),
                 choiceValues = list("bp", "glu"),
                 selected = s("domain", "bp"), inline = TRUE),
    conditionalPanel(
      condition = "input.domain == 'bp'",
      checkboxInput("use_builtin_data", tr2("use_builtin"), value = s("use_builtin_data", FALSE)),
      checkboxInput("use_device_sample", tr2("use_device_sample"), value = s("use_device_sample", TRUE)),
      p(tr2("device_sample_hint"), style = "font-size:0.85em;color:#555;"),
      if (!DEMO_MODE) {
        tagList(
          radioButtons("upload_mode", tr2("upload_mode_label"),
                       choiceNames = list(tr2("upload_mode_csv"), tr2("upload_mode_raw")),
                       choiceValues = list("csv", "raw"),
                       selected = s("upload_mode", "csv")),
          conditionalPanel(
            condition = "input.upload_mode == 'csv'",
            fileInput("csv_files", tr2("choose_csv_files"), multiple = TRUE,
                      accept = c("text/csv", "text/comma-separated-values,text/plain", ".csv")),
            p(tr2("csv_hint"), style = "font-size:0.85em;color:#555;")
          ),
          conditionalPanel(
            condition = "input.upload_mode == 'raw'",
            fileInput("raw_files", tr2("choose_raw_files"), multiple = TRUE,
                      accept = c(".xls", ".xlsx", "application/vnd.ms-excel")),
            p(tr2("raw_hint"), style = "font-size:0.85em;color:#555;")
          )
        )
      } else {
        p(icon("lock"), tr2("demo_mode_note"), style = "font-size:0.85em;color:#666;")
      }
    ),
    conditionalPanel(
      condition = "input.domain == 'glu'",
      checkboxInput("use_glucose_sample", tr2("use_glucose_sample"),
                    value = s("use_glucose_sample", FALSE)),
      if (!DEMO_MODE) {
        tagList(
          fileInput("glu_csv_files", tr2("choose_glu_csv_files"), multiple = TRUE,
                    accept = c("text/csv", "text/comma-separated-values,text/plain", ".csv")),
          p(tr2("glu_csv_hint"), style = "font-size:0.85em;color:#555;"),
          fileInput("glu_raw_files", tr2("choose_glu_raw_files"), multiple = TRUE,
                    accept = c(".xlsx", ".xls", "application/vnd.ms-excel")),
          p(tr2("glu_raw_hint"), style = "font-size:0.85em;color:#555;")
        )
      } else {
        p(icon("lock"), tr2("demo_mode_note"), style = "font-size:0.85em;color:#666;")
      }
    ),
    uiOutput("mapping_panel"),
    uiOutput("raw_convert_panel"),
    wellPanel(
      style = "padding: 10px; background-color: #f8f9fa;",
      p(icon("info-circle"), tags$strong(tr2("format_help_title"))),
      tags$ul(style = "font-size: 0.85em; padding-left: 20px; color: #333;",
              tags$li(tr2("format_help_1")),
              tags$li(tr2("format_help_2")),
              tags$li(tr2("format_help_3")),
              tags$li(tr2("format_help_4")),
              tags$li(tr2("format_help_5")),
              tags$li(tr2("format_help_6")),
              tags$li(tr2("format_help_7")))
    ),
    hr(),

    h4(icon("clock"), tr2("daynight_title")),
    time_row("day1_start_h", "day1_start_m", tr2("day1_start"), 7, 0),
    time_row("day1_night_start_h", "day1_night_start_m", tr2("night1_start"), 22, 0),
    time_row("day2_start_h", "day2_start_m", tr2("day2_start"), 7, 0),
    time_row("day2_night_start_h", "day2_night_start_m", tr2("night2_start"), 22, 0),
    h5(tr2("preset_title"), style = "margin-top: 15px; margin-bottom: 5px;"),
    fluidRow(
      column(6, actionButton("preset_east_asia", tr2("preset_east"), class = "btn-sm btn-block btn-info")),
      column(6, actionButton("preset_western", tr2("preset_west"), class = "btn-sm btn-block btn-primary"))
    ),
    hr(),

    h4(icon("chart-line"), tr2("interp_title")),
    radioButtons("interp_mode", NULL,
                 choiceNames = list(
                   HTML(paste0("<b>", tr2("interp_mode_valid_name"), "</b><br><small>",
                               tr2("interp_valid_desc"), "</small>")),
                   HTML(paste0("<b>", tr2("interp_mode_full_name"), "</b><br><small>",
                               tr2("interp_full_desc"), "</small>"))
                 ),
                 choiceValues = list("valid", "full"),
                 selected = s("interp_mode", "valid")),
    p(tr2("interp_note"), style = "font-size:0.85em;color:#555;"),
    hr(),

    h4(icon("crop-alt"), tr2("window_title")),
    radioButtons("window_mode", NULL,
                 choiceNames = list(tr2("window_mode_calendar"),
                                    tr2("window_mode_from_first"),
                                    tr2("window_mode_from_start"),
                                    tr2("window_mode_custom")),
                 choiceValues = list("calendar", "from_first", "from_start", "custom"),
                 selected = s("window_mode", "from_first")),
    conditionalPanel(
      condition = "input.window_mode == 'from_first'",
      numericInput("window_hours", tr2("window_hours"),
                   value = s("window_hours", 24), min = 1, max = 168, step = 1)
    ),
    conditionalPanel(
      condition = "input.window_mode == 'from_start'",
      textInput("window_start_spec", tr2("window_start_spec"),
                value = s("window_start_spec", ""), placeholder = "HHMM+XD, e.g. 0800+0D"),
      numericInput("window_hours", tr2("window_hours"),
                   value = s("window_hours", 24), min = 1, max = 168, step = 1)
    ),
    conditionalPanel(
      condition = "input.window_mode == 'custom'",
      textInput("window_start_spec", tr2("window_start_spec"),
                value = s("window_start_spec", ""), placeholder = "HHMM+XD, e.g. 0800+0D"),
      textInput("window_end_spec", tr2("window_end_spec"),
                value = s("window_end_spec", ""), placeholder = "HHMM+XD, e.g. 0800+1D")
    ),
    p(tr2("window_hint"), style = "font-size:0.85em;color:#555;"),
    hr(),

    h4(icon("wave-square"), tr2("vim_title")),
    radioButtons("vim_mode", NULL,
                 choiceNames = list(tr2("vim_mode_cohort"), tr2("vim_mode_fixed")),
                 choiceValues = list("cohort", "fixed"),
                 selected = s("vim_mode", "cohort")),
    conditionalPanel(
      condition = "input.vim_mode == 'fixed'",
      numericInput("vim_ref_mean", tr2("vim_ref_mean"),
                   value = s("vim_ref_mean", 100), min = 1, max = 400, step = 1)
    ),
    wellPanel(
      style = "padding: 10px; background-color: #f8f9fa;",
      h5(tags$strong(tr2("vim_formula_title")), style = "margin-top:0;"),
      withMathJax(helpText("$$VIM = \\frac{SD}{\\bar{x}^{\\beta}} \\times k$$")),
      tags$ul(style = "font-size: 0.85em; padding-left: 20px;",
              tags$li(tags$strong(tr2("vim_mode_cohort"), ": "), tr2("vim_cohort_text")),
              tags$li(tags$strong(tr2("vim_mode_fixed"), ": "), tr2("vim_fixed_text")),
              tags$li(tags$strong(tr2("key_overview"), ": "), tr2("vim_meaning_text")),
              tags$li(tags$strong(tr2("vim_params_text")), tr2("vim_insufficient")))
    ),
    hr(),

    div(style = "margin-bottom: 10px;",
        actionButton("process_data_btn", tr2("process_btn"), icon = icon("cogs"),
                     class = "btn-primary btn-lg btn-block")),
    hr(),

    h4(icon("bullseye"), tr2("targets_title")),
    div(class = "alert alert-info",
        style = "padding:8px 10px; margin-bottom:10px; font-size:0.9em;",
        tr2("targets_hint")),
    tabsetPanel(
      id = "target_tabs",
      tabPanel(tr2("tab_day"), target_tab("day")),
      tabPanel(tr2("tab_night"), target_tab("night")),
      tabPanel(tr2("tab_24h"), target_tab("24h")),
      tabPanel(tr2("tab_glu"),
               p(tr2("glu_targets_hint"), style = "font-size:0.85em;color:#555;"),
               fluidRow(column(6, numericInput("glu_day_lower", paste0("GLU ", tr2("lower"), " (mmol/L)"),
                                               value = s("glu_day_lower", 3.9))),
                        column(6, numericInput("glu_day_upper", paste0("GLU ", tr2("upper"), " (mmol/L)"),
                                               value = s("glu_day_upper", 10.0)))),
               fluidRow(column(6, numericInput("glu_night_lower", paste0("GLU ", tr2("lower"), " (mmol/L)"),
                                               value = s("glu_night_lower", 3.9))),
                        column(6, numericInput("glu_night_upper", paste0("GLU ", tr2("upper"), " (mmol/L)"),
                                               value = s("glu_night_upper", 10.0)))),
               fluidRow(column(6, numericInput("glu_24h_lower", paste0("GLU ", tr2("lower"), " (mmol/L)"),
                                               value = s("glu_24h_lower", 3.9))),
                        column(6, numericInput("glu_24h_upper", paste0("GLU ", tr2("upper"), " (mmol/L)"),
                                               value = s("glu_24h_upper", 10.0)))),
               fluidRow(
                 column(6, actionButton("preset_glu_normal", tr2("glu_preset_normal"),
                                        class = "btn-sm btn-block btn-info",
                                        style = "margin-top: 6px;")),
                 column(6, actionButton("preset_glu_diabetes", tr2("glu_preset_diabetes"),
                                        class = "btn-sm btn-block btn-warning",
                                        style = "margin-top: 6px;"))
               ))
    ),
    actionButton("apply_targets_btn", tr2("apply_targets_btn"), icon = icon("magic"),
                 class = "btn-sm btn-info btn-block", style = "margin-top: 10px;"),
    actionButton("preset_targets", tr2("preset_targets_btn"), icon = icon("bullseye"),
                 class = "btn-sm btn-warning btn-block", style = "margin-top: 5px;"),
    shinyjs::disabled(
      actionButton("save_custom_targets_btn", tr2("save_targets_btn"), icon = icon("lock"),
                   class = "btn-sm btn-success btn-block", style = "margin-top: 5px; margin-bottom: 10px;")
    ),
    hr(),

    div(style = "margin-bottom: 10px;",
        shinyjs::disabled(
          actionButton("calculate_metrics_btn", tr2("calc_btn"), icon = icon("calculator"),
                       class = "btn-success btn-lg btn-block")
        )),
    hr(),

    h4(icon("download"), tr2("export_title")),
    checkboxGroupInput("export_items", tr2("export_select"),
                       choices = setNames(
                         c("wide", "period", "personal", "prepared", "interp", "split"),
                         c(tr2("export_wide"), tr2("export_period"), tr2("export_personal"),
                           tr2("export_prepared"), tr2("export_interp"), tr2("export_split"))),
                       selected = s("export_items", c("wide", "period", "personal"))),
    downloadButton("download_sel_csv", tr2("export_csv_btn"), class = "btn-info btn-block"),
    downloadButton("download_sel_xlsx", tr2("export_xlsx_btn"), class = "btn-success btn-block",
                   style = "margin-top: 5px;")
  ) # end sidebarPanel

  main <- mainPanel(
    width = 9,
    tabsetPanel(id = "main_tabset", type = "tabs",
                selected = s("main_tabset", "raw_data_tab"),

                # ---- View input data ----
                tabPanel(title = span(icon("file-alt"), tr2("tab_input")), value = "raw_data_tab",
                         br(), h4(textOutput("data_source_title")),
                         uiOutput("data_status_line"),
                         DTOutput("raw_data_table"),
                         hr(),
                         h5(tr2("raw_summary_title")), DTOutput("raw_convert_summary"),
                         h5(tr2("raw_preview_title")), DTOutput("raw_convert_preview")),

                # ---- Processed data ----
                tabPanel(title = span(icon("wrench"), tr2("tab_processed")), value = "processed_data_tab",
                         br(),
                         tabsetPanel(id = "processing_subtabs",
                                     tabPanel(title = tr2("subtab_prepared"), value = "prepared_long",
                                              br(), h5(tr2("caption_prepared")), DTOutput("prepared_long_table"),
                                              hr(), h5(paste0(tr2("caption_wide"), "(pre-interpolation)")),
                                              uiOutput("wide_data_tabs")),
                                     tabPanel(title = tr2("subtab_interp"), value = "wide_interpolated",
                                              br(), h5(tr2("caption_interp")),
                                              uiOutput("interpolated_data_tabs")))),

                # ---- Segmented data ----
                tabPanel(title = span(icon("columns"), tr2("tab_split")), value = "split_data_tab",
                         br(), h5(tr2("progress_split")),
                         tabsetPanel(id = "split_period_tabs",
                                     tabPanel(title = span(icon("cloud-moon"), tr2("split_day0night")), value = "day0_night",
                                              br(), uiOutput("split_day0_night_metric_tabs")),
                                     tabPanel(title = span(icon("sun"), tr2("split_day1day")), value = "day1_day",
                                              br(), uiOutput("split_day1_day_metric_tabs")),
                                     tabPanel(title = span(icon("moon"), tr2("split_day1night")), value = "day1_night",
                                              br(), uiOutput("split_day1_night_metric_tabs")),
                                     tabPanel(title = span(icon("cloud-sun"), tr2("split_day2day")), value = "day2_day",
                                              br(), uiOutput("split_day2_day_metric_tabs")),
                                     tabPanel(title = span(icon("hourglass-half"), tr2("split_24h_interp")), value = "full_24h_interp",
                                              br(), h5(tr2("caption_full_interp")),
                                              uiOutput("full_24h_interpolated_data_tabs")))),

                # ---- Metric results ----
                tabPanel(title = span(icon("table"), tr2("tab_results")), value = "results_tab",
                         br(),
                         fluidRow(
                           column(12,
                                  tags$p(paste0(tr2("export_title"), " → ",
                                                tr2("export_csv_btn"), " / ", tr2("export_xlsx_btn")),
                                         style = "text-align:right; color:#666; margin-bottom:8px; font-size:0.9em;"))
                         ),
                         tabsetPanel(id = "results_period_tabs",
                                     tabPanel(title = tr2("results_day"), value = "day_results",
                                              br(), uiOutput("target_ranges_day_display"),
                                              hr(style = "border-top: 1px solid #ccc;"),
                                              uiOutput("day_metric_tabs")),
                                     tabPanel(title = tr2("results_night"), value = "night_results",
                                              br(), uiOutput("target_ranges_night_display"),
                                              hr(style = "border-top: 1px solid #ccc;"),
                                              uiOutput("night_metric_tabs")),
                                     tabPanel(title = tr2("results_24h_unified"), value = "results_24h_unified",
                                              br(), uiOutput("target_ranges_24h_unified_display"),
                                              hr(style = "border-top: 1px solid #ccc;"),
                                              uiOutput("24h_unified_metric_tabs")),
                                     tabPanel(title = tr2("results_24h_segmented"), value = "results_24h_segmented",
                                              br(), uiOutput("target_ranges_daynight_display_combined"),
                                              hr(style = "border-top: 1px solid #ccc;"),
                                              uiOutput("segmented_24h_metric_tabs")))),

                # ---- Visualization ----
                tabPanel(title = span(icon("chart-area"), tr2("tab_viz")), value = "viz_tab",
                         br(),
                         fluidRow(
                           column(4,
                                  wellPanel(
                                    style = "background-color: #f8f9fa; border-radius: 5px; padding: 15px; border: 1px solid #ddd;",
                                    selectInput("viz_maskid", label = tagList(icon("user"), tr2("choose_patient")),
                                                choices = NULL, width = "100%"),
                                    selectInput("viz_metric_select", label = tagList(icon("stethoscope"), tr2("choose_metric")),
                                                choices = c("SBP", "DBP", "HR", "PP", "MAP", "GLU"),
                                                selected = s("viz_metric_select", "SBP"), width = "100%")
                                  )),
                           column(8,
                                  wellPanel(
                                    class = "summary-well",
                                    h5(icon("binoculars"), tr2("viz_overview_title"), style = "color: #0056b3;"),
                                    uiOutput("viz_summary_header")))
                         ),
                         hr(),
                         tabsetPanel(id = "viz_sub_tabset", type = "pills",
                                     tabPanel(title = span(icon("hourglass-half"), tr2("viz_24h_unified")), value = "viz_24h_unified",
                                              br(),
                                              fluidRow(
                                                column(6, wellPanel(class = "summary-well",
                                                                    h5(icon("clipboard-check"), paste0(tr2("key_overview"), " (", tr2("viz_24h_unified"), ")")),
