                                              br(),
                                              fluidRow(
                                                column(12, div(class = "plot-well",
                                                               div(class = "plot-well-header", icon("chart-line"), tr2("trend_title")),
                                                               div(class = "plot-well-body", plotlyOutput("bp_trend_chart_24h_segmented_limits", height = "450px"))))
                                              ),
                                              br(),
                                              p(tags$strong(tr2("seg_results_title")), style = "font-size: 1.1em; color: #286090;"),
                                              p(em(tr2("seg_results_note")), style = "font-style: italic;"),
                                              fluidRow(
                                                column(6, wellPanel(class = "summary-well", style = "background-color: #e8f5e9; border-color: #c8e6c9;",
                                                                    h5(icon("clipboard-check"), paste0(tr2("key_overview"), " (", tr2("viz_24h_segmented"), ")")),
                                                                    uiOutput("viz_info_24h_segmented"))),
                                                column(6, wellPanel(class = "stats-well",
                                                                    h5(icon("clipboard-list"), paste0(tr2("stats_summary"), " (", tr2("viz_24h_segmented"), ")")),
                                                                    verbatimTextOutput("patient_summary_24h_segmented")))
                                              ),
                                              fluidRow(
                                                column(4, div(class = "plot-well",
                                                              div(class = "plot-well-header", icon("chart-pie"), tr2("donut_title")),
                                                              div(class = "plot-well-body", plotlyOutput("time_in_range_donut_24h_segmented", height = "350px")))),
                                                column(4, div(class = "plot-well",
                                                              div(class = "plot-well-header", icon("tachometer-alt"), tr2("burden_title")),
                                                              div(class = "plot-well-body", plotlyOutput("burden_chart_24h_segmented", height = "350px")))),
                                                column(4, div(class = "plot-well",
                                                              div(class = "plot-well-header", icon("wave-square"), tr2("variability_title")),
                                                              div(class = "plot-well-body", plotlyOutput("variability_chart_24h_segmented", height = "350px"))))
                                              )),
                                     tabPanel(title = span(icon("sun"), tr2("viz_day")), value = "viz_day",
                                              br(),
                                              fluidRow(
                                                column(6, wellPanel(class = "summary-well",
                                                                    h5(icon("clipboard-check"), paste0(tr2("key_overview"), " (", tr2("viz_day"), ")")),
                                                                    uiOutput("viz_info_day"))),
                                                column(6, wellPanel(class = "stats-well",
                                                                    h5(icon("clipboard-list"), paste0(tr2("stats_summary"), " (", tr2("viz_day"), ")")),
                                                                    verbatimTextOutput("patient_summary_day")))
                                              ),
                                              fluidRow(
                                                column(12, div(class = "plot-well",
                                                               div(class = "plot-well-header", icon("chart-line"), tr2("trend_title")),
                                                               div(class = "plot-well-body", plotlyOutput("bp_trend_chart_day", height = "450px"))))
                                              ),
                                              br(),
                                              fluidRow(
                                                column(4, div(class = "plot-well",
                                                              div(class = "plot-well-header", icon("chart-pie"), tr2("donut_title")),
                                                              div(class = "plot-well-body", plotlyOutput("time_in_range_donut_day", height = "350px")))),
                                                column(4, div(class = "plot-well",
                                                              div(class = "plot-well-header", icon("tachometer-alt"), tr2("burden_title")),
                                                              div(class = "plot-well-body", plotlyOutput("burden_chart_day", height = "350px")))),
                                                column(4, div(class = "plot-well",
                                                              div(class = "plot-well-header", icon("wave-square"), tr2("variability_title")),
                                                              div(class = "plot-well-body", plotlyOutput("variability_chart_day", height = "350px"))))
                                              )),
                                     tabPanel(title = span(icon("moon"), tr2("viz_night")), value = "viz_night",
                                              br(),
                                              fluidRow(
                                                column(6, wellPanel(class = "summary-well",
                                                                    h5(icon("clipboard-check"), paste0(tr2("key_overview"), " (", tr2("viz_night"), ")")),
                                                                    uiOutput("viz_info_night"))),
                                                column(6, wellPanel(class = "stats-well",
                                                                    h5(icon("clipboard-list"), paste0(tr2("stats_summary"), " (", tr2("viz_night"), ")")),
                                                                    verbatimTextOutput("patient_summary_night")))
                                              ),
                                              fluidRow(
                                                column(12, div(class = "plot-well",
                                                               div(class = "plot-well-header", icon("chart-line"), tr2("trend_title")),
                                                               div(class = "plot-well-body", plotlyOutput("bp_trend_chart_night", height = "450px"))))
                                              ),
                                              br(),
                                              fluidRow(
                                                column(4, div(class = "plot-well",
                                                              div(class = "plot-well-header", icon("chart-pie"), tr2("donut_title")),
                                                              div(class = "plot-well-body", plotlyOutput("time_in_range_donut_night", height = "350px")))),
                                                column(4, div(class = "plot-well",
                                                              div(class = "plot-well-header", icon("tachometer-alt"), tr2("burden_title")),
                                                              div(class = "plot-well-body", plotlyOutput("burden_chart_night", height = "350px")))),
                                                column(4, div(class = "plot-well",
                                                              div(class = "plot-well-header", icon("wave-square"), tr2("variability_title")),
                                                              div(class = "plot-well-body", plotlyOutput("variability_chart_night", height = "350px"))))
                                              ))
                         )),

                # ---- Personalized analysis ----
                tabPanel(title = span(icon("user-check"), tr2("tab_personal")), value = "personal_analysis_tab",
                         br(),
                         fluidRow(
                           column(4,
                                  wellPanel(
                                    selectInput("analysis_maskid", tr2("choose_patient"), choices = NULL, width = "100%"),
                                    p(style = "font-size:0.85em;color:#666;", tr2("personal_note")))),
                           column(8,
                                  wellPanel(class = "summary-well",
                                            h5(icon("notes-medical"), tr2("followup_title")),
                                            uiOutput("personal_followup_level")))
                         ),
                         h4(icon("project-diagram"), tr2("dims_title")),
                         DTOutput("personal_dimension_table"),
                         br(),
                         h4(icon("book-medical"), tr2("guidelines_title")),
                         DTOutput("personal_guideline_table"),
                         br(),
                         h4(icon("comment-medical"), tr2("advice_title")),
                         uiOutput("personal_advice"),
                         br(), hr(),
                         # Glucose (CGM) block, rendered only when GLU results exist
                         uiOutput("personal_glu_block"),
                         wellPanel(
                           style = "font-size:0.85em;color:#555;",
                           tags$strong(paste0(tr2("tab_guide"), ": ")),
                           tr2("disclaimer"),
                           tags$br(),
                           a("ESC 2024", href = "https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/elevated-blood-pressure-and-hypertension/", target = "_blank"),
                           "; ",
                           a("AHA/ACC 2025", href = "https://professional.heart.org/en/science-news/2025-high-blood-pressure-guideline", target = "_blank"),
                           "; ",
                           a(if (lang == "zh") "中国高血压防治指南（2024年修订版）" else "Chinese Hypertension Guideline (2024 revision)",
                             href = "https://pmc.ncbi.nlm.nih.gov/articles/PMC11937835/", target = "_blank")
                         )),

                # ---- Field definitions ----
                tabPanel(title = span(icon("list-alt"), tr2("tab_fielddefs")), value = "field_defs_tab",
                         br(), h4(tr2("field_defs_title")),
                         DTOutput("field_defs_table")),

                # ---- User guide ----
                tabPanel(title = span(icon("question-circle"), tr2("tab_guide")), value = "guide_tab",
                         br(),
                         build_guide_ui(lang),
                         build_author_panel(lang))
    ) # end main tabset
  ) # end mainPanel

  # sidebarPanel(width=3) + mainPanel(width=9) must live directly inside
  # sidebarLayout(); wrapping them in fluidRow/column would double-apply the
  # width rules and break the layout ratio.
  sidebarLayout(sidebar, main)
}

# --- 4. Server Logic (integrated bilingual server) ---
# --- 4. Server Logic (bilingual shell, target helpers, pipeline state) ---
server <- function(input, output, session) {

  # ---------------- Bilingual state ----------------
  lang <- reactiveVal("en")
  observeEvent(input$lang_radio, { lang(input$lang_radio) }, ignoreNULL = TRUE)
  observe({ APP_LANG <<- lang() }) # chart/table helpers read this

  # Snapshot of user settings so a language switch re-renders the page without
  # losing inputs. build_ui() reads this snapshot (isolated), so the page only
  # re-renders when the language changes.
  settings <- reactiveValues()
  SNAPSHOT_INPUT_IDS <- c(
    "domain", "use_builtin_data", "use_device_sample", "use_glucose_sample", "upload_mode",
    "day1_start_h", "day1_start_m", "day1_night_start_h", "day1_night_start_m",
    "day2_start_h", "day2_start_m", "day2_night_start_h", "day2_night_start_m",
    "interp_mode", "vim_mode", "vim_ref_mean",
    "window_mode", "window_hours", "window_start_spec", "window_end_spec",
    unlist(lapply(c("sbp", "dbp", "hr", "pp", "map"), function(m) {
      unlist(lapply(c("day", "night", "24h"), function(p) {
        paste0(m, "_", p, "_", c("lower", "upper"))
      }), use.names = FALSE)
    }), use.names = FALSE),
    "map_id", "map_time", "map_sbp", "map_dbp", "map_hr", "map_pp", "map_map",
    "export_items", "main_tabset", "viz_metric_select"
  )
  observe({
    for (id in SNAPSHOT_INPUT_IDS) {
      val <- input[[id]]
      if (!is.null(val)) settings[[id]] <- val
    }
  })

  output$page <- renderUI({
    build_ui(lang(), isolate(reactiveValuesToList(settings)))
  })

  output$header_title <- renderUI({
    div(
      icon("heart-pulse"),
      tr(lang(), "app_title"),
      span(tr(lang(), "app_title_sub"), style = "font-size: 0.7em; color: #555; margin-left: 8px;")
    )
  })

  output$footer_text <- renderUI({
    tagList(
      div(tr(lang(), "footer_copyright")),
      div(tr(lang(), "footer_contact"), " ",
          a("morethanlee@163.com", href = "mailto:morethanlee@163.com"))
    )
  })

  observe({
    updateActionButton(session, "tour_btn", label = tr(lang(), "tour_start"))
  })

  # ---------------- Guided tour (rintrojs) ----------------
  observeEvent(input$tour_btn, {
    if (!has_introjs) {
      showNotification(tr(lang(), "tour_unavailable"), type = "warning", duration = 5)
      updateTabsetPanel(session, "main_tabset", selected = "guide_tab")
      return()
    }
    tour_elements <- c("#lang_radio", "#domain", "#use_builtin_data", "#use_device_sample")
    tour_intros <- c(tr(lang(), "tour_step_lang"),
                     tr(lang(), "tour_step_domain"),
                     tr(lang(), "tour_step_builtin"),
                     tr(lang(), "tour_step_device_sample"))
    if (!DEMO_MODE) {
      tour_elements <- c(tour_elements, "#upload_mode")
      tour_intros <- c(tour_intros, tr(lang(), "tour_step_mode"))
    }
    tour_elements <- c(tour_elements,
                       "#day1_start_h", "#interp_mode", "#window_mode", "#vim_mode",
                       "#sbp_day_lower", "#process_data_btn", "#calculate_metrics_btn",
                       "#main_tabset", "#export_items", "#download_sel_csv")
    tour_intros <- c(tour_intros,
                     tr(lang(), "tour_step_daynight"), tr(lang(), "tour_step_interp"),
                     tr(lang(), "tour_step_window"), tr(lang(), "tour_step_vim"),
                     tr(lang(), "tour_step_targets"),
                     tr(lang(), "tour_step_process"), tr(lang(), "tour_step_calc"),
                     tr(lang(), "tour_step_tabs"), tr(lang(), "tour_step_export"),
                     tr(lang(), "tour_step_download"))
    steps <- data.frame(element = tour_elements, intro = tour_intros,
                        stringsAsFactors = FALSE)
    rintrojs::introjs(session, options = list(
      steps = steps,
      nextLabel = tr(lang(), "tour_next"),
      prevLabel = tr(lang(), "tour_prev"),
      skipLabel = tr(lang(), "tour_skip"),
      doneLabel = tr(lang(), "tour_done")
    ))
  }, ignoreInit = TRUE)

  # ---------------- Reactive values ----------------
  values <- reactiveValues(
    raw_data_input = NULL,
    prepared_long_data = NULL,
    wide_dfs = list(),
    individual_series = list(),
    interpolated_dfs = list(),
    sorted_times = NULL,
    sorted_minutes = NULL,
    split_data_wide = list(),
    metric_results = list(day = list(), night = list(), `24h` = list(), `24h_segmented` = list()),
    processing_error = NULL,
    calculation_error = NULL,
    data_processed_successfully = FALSE,
    metrics_calculated_successfully = FALSE,
    data_source_key = "src_none",
    targets_used_day = list(),
    targets_used_night = list(),
    targets_used_24h = list(),
    available_patients_viz = character(0),
    selected_patient_viz = NULL,
    selected_metric_viz = "SBP",
    targets_locked = FALSE,
    locked_targets = NULL,
    # new import-related state
    use_builtin_active = FALSE,
    device_sample_active = FALSE,
    glucose_sample_active = FALSE,
    # analysis window state
    edge_rule = "linear",
    pending_window_args = NULL,
    uploaded_csv_raw = NULL,
    uploaded_csv_files = character(0),
    raw_files_info = list(),
    raw_maskids = list(),
    converted_raw_long = NULL,
    converted_raw_summary = NULL
  )

  # --- Target-range state helpers ---
  # Keep every target input in one place so the lock button controls the full
  # target set consistently (including PP/MAP).
  TARGET_INPUT_IDS <- unlist(lapply(c("sbp", "dbp", "hr", "pp", "map", "glu"), function(metric_name) {
    unlist(lapply(c("day", "night", "24h"), function(period_name) {
      paste0(metric_name, "_", period_name, "_", c("lower", "upper"))
    }), use.names = FALSE)
  }), use.names = FALSE)

  read_current_targets <- function() {
    list(
      sbp_day_lower = input$sbp_day_lower, sbp_day_upper = input$sbp_day_upper,
      dbp_day_lower = input$dbp_day_lower, dbp_day_upper = input$dbp_day_upper,
      hr_day_lower = input$hr_day_lower, hr_day_upper = input$hr_day_upper,
      pp_day_lower = input$pp_day_lower, pp_day_upper = input$pp_day_upper,
      map_day_lower = input$map_day_lower, map_day_upper = input$map_day_upper,
      sbp_night_lower = input$sbp_night_lower, sbp_night_upper = input$sbp_night_upper,
      dbp_night_lower = input$dbp_night_lower, dbp_night_upper = input$dbp_night_upper,
      hr_night_lower = input$hr_night_lower, hr_night_upper = input$hr_night_upper,
      pp_night_lower = input$pp_night_lower, pp_night_upper = input$pp_night_upper,
      map_night_lower = input$map_night_lower, map_night_upper = input$map_night_upper,
      sbp_24h_lower = input$sbp_24h_lower, sbp_24h_upper = input$sbp_24h_upper,
      dbp_24h_lower = input$dbp_24h_lower, dbp_24h_upper = input$dbp_24h_upper,
      hr_24h_lower = input$hr_24h_lower, hr_24h_upper = input$hr_24h_upper,
      pp_24h_lower = input$pp_24h_lower, pp_24h_upper = input$pp_24h_upper,
      map_24h_lower = input$map_24h_lower, map_24h_upper = input$map_24h_upper,
      glu_day_lower = input$glu_day_lower, glu_day_upper = input$glu_day_upper,
      glu_night_lower = input$glu_night_lower, glu_night_upper = input$glu_night_upper,
      glu_24h_lower = input$glu_24h_lower, glu_24h_upper = input$glu_24h_upper
    )
  }

  target_is_missing <- function(x) {
    length(x) == 0L || (length(x) == 1L && is.na(x))
  }

  target_is_finite_number <- function(x) {
    length(x) == 1L && is.numeric(x) && !is.na(x) && is.finite(x)
  }

  period_label <- function(period) tr(APP_LANG, paste0("tab_", period))

  validate_optional_target_pairs <- function(targets) {
    for (metric_name in c("pp", "map")) {
      for (period_name in c("day", "night", "24h")) {
        lower <- targets[[paste0(metric_name, "_", period_name, "_lower")]]
        upper <- targets[[paste0(metric_name, "_", period_name, "_upper")]]
        lower_missing <- target_is_missing(lower)
        upper_missing <- target_is_missing(upper)
        label <- paste(period_label(period_name), toupper(metric_name))

        if (xor(lower_missing, upper_missing)) {
          return(list(valid = FALSE,
                      message = paste0(label, tr(APP_LANG, "pair_err"))))
        }
        if (!lower_missing &&
            (!target_is_finite_number(lower) || !target_is_finite_number(upper))) {
          return(list(valid = FALSE,
                      message = paste0(label, tr(APP_LANG, "pair_err_num"))))
        }
      }
    }
    list(valid = TRUE, message = NULL)
  }

  validate_target_snapshot <- function(targets) {
    required_names <- grep("^(sbp|dbp|hr|glu)_.*_(lower|upper)$", names(targets), value = TRUE)
    invalid_required <- vapply(targets[required_names], function(x) {
      length(x) != 1L || !is.numeric(x) || is.na(x) || !is.finite(x)
    }, logical(1))
    if (any(invalid_required)) {
      return(list(valid = FALSE, message = tr(APP_LANG, "lock_err_required")))
    }

    optional_names <- grep("^(pp|map)_.*_(lower|upper)$", names(targets), value = TRUE)
    invalid_optional <- vapply(targets[optional_names], function(x) {
      length(x) > 1L || (length(x) == 1L && !is.na(x) && (!is.numeric(x) || !is.finite(x)))
    }, logical(1))
    if (any(invalid_optional)) {
      return(list(valid = FALSE, message = tr(APP_LANG, "lock_err_optional")))
    }

    optional_pair_validation <- validate_optional_target_pairs(targets)
    if (!isTRUE(optional_pair_validation$valid)) return(optional_pair_validation)

    for (metric_name in c("sbp", "dbp", "hr", "pp", "map", "glu")) {
      for (period_name in c("day", "night", "24h")) {
        lower <- targets[[paste0(metric_name, "_", period_name, "_lower")]]
        upper <- targets[[paste0(metric_name, "_", period_name, "_upper")]]
        if (length(lower) == 1L && length(upper) == 1L &&
            is.numeric(lower) && !is.na(lower) && is.numeric(upper) && !is.na(upper) &&
            upper <= lower) {
          label <- paste(period_label(period_name), toupper(metric_name))
          return(list(valid = FALSE,
                      message = paste0(label, tr(APP_LANG, "lock_err_order"))))
        }
      }
    }

    list(valid = TRUE, message = NULL)
  }

  set_target_controls_locked <- function(locked) {
    for (target_id in TARGET_INPUT_IDS) {
      if (isTRUE(locked)) shinyjs::disable(target_id) else shinyjs::enable(target_id)
    }

    if (isTRUE(locked)) {
      shinyjs::disable("apply_targets_btn")
      shinyjs::disable("preset_targets")
      shinyjs::disable("preset_glu_normal")
      shinyjs::disable("preset_glu_diabetes")
      updateActionButton(session, "save_custom_targets_btn",
                         label = tr(APP_LANG, "unlock_targets_btn"), icon = icon("unlock"))
    } else {
      shinyjs::enable("apply_targets_btn")
      shinyjs::enable("preset_targets")
      shinyjs::enable("preset_glu_normal")
      shinyjs::enable("preset_glu_diabetes")
      updateActionButton(session, "save_custom_targets_btn",
                         label = tr(APP_LANG, "save_targets_btn"), icon = icon("lock"))
    }
  }

  # --- Placeholder Variability Reference Values ---
  VARIABILITY_REFERENCE_VALUES <- list(
    "SBP" = list(sd = 15, arv = 12),
    "DBP" = list(sd = 12, arv = 10),
    "HR" = list(sd = 10, arv = 8),
    "PP" = list(sd = 8, arv = 6), # Example values, adjust as needed
    "MAP" = list(sd = 10, arv = 8), # Example values, adjust as needed
    "GLU" = list(sd = 2.0, arv = 0.6) # Example values (mmol/L), adjust as needed
  )

  # --- Data loading: built-in sample / prepared CSV (multi-file, with column
  #     mapping) / raw Mobil-O-Graph 24h PWA exports ---
  reset_pipeline_state <- function() {
    values$prepared_long_data <- NULL; values$wide_dfs <- list()
    values$individual_series <- list(); values$interpolated_dfs <- list()
    values$sorted_times <- NULL; values$sorted_minutes <- NULL
    values$split_data_wide <- list()
    values$processing_error <- NULL; values$calculation_error <- NULL
    values$metric_results <- list(day = list(), night = list(), `24h` = list(), `24h_segmented` = list())
    values$data_processed_successfully <- FALSE
    values$metrics_calculated_successfully <- FALSE
    values$targets_used_day <- list(); values$targets_used_night <- list(); values$targets_used_24h <- list()
    values$available_patients_viz <- character(0)
    values$selected_patient_viz <- NULL
    values$targets_locked <- FALSE
    values$locked_targets <- NULL
    shinyjs::disable("calculate_metrics_btn")
    shinyjs::disable("save_custom_targets_btn")
    set_target_controls_locked(FALSE)
  }

  read_csv_smart <- function(path, name) {
    tryCatch(
      read.csv(path, check.names = FALSE, stringsAsFactors = FALSE,
               na.strings = c("", "NA", "NULL", " "), fileEncoding = "UTF-8-BOM"),
      error = function(e1) {
        tryCatch(
          read.csv(path, check.names = FALSE, stringsAsFactors = FALSE,
                   na.strings = c("", "NA", "NULL", " ")),
          error = function(e2) {
            stop(tr(lang(), "err_csv_read"), ": ", name, " (", e2$message, ")")
          }
        )
      }
    )
  }

  # Built-in demo data (prepared-CSV path)
  observeEvent(input$use_builtin_data, {
    if (!isTRUE(input$use_builtin_data)) return()
    if (isTRUE(values$use_builtin_active) && !is.null(values$raw_data_input)) return()
    reset_pipeline_state()
    tryCatch({
      df <- read.csv(text = csv_data_string, check.names = FALSE,
                     stringsAsFactors = FALSE, na.strings = c("", "NA", "NULL", " "))
      if (!is.data.frame(df) || nrow(df) == 0) stop("built-in data is empty")
      values$raw_data_input <- df
      values$uploaded_csv_raw <- NULL
      values$raw_files_info <- list()
      values$use_builtin_active <- TRUE
      values$device_sample_active <- FALSE
      updateCheckboxInput(session, "use_device_sample", value = FALSE)
      values$glucose_sample_active <- FALSE
      updateCheckboxInput(session, "use_glucose_sample", value = FALSE)
      values$data_source_key <- "src_builtin"
      showNotification(tr(lang(), "builtin_loaded"), type = "message", duration = 4)
    }, error = function(e) {
      showNotification(paste(tr(lang(), "err_csv_read"), ":", e$message),
                       type = "error", duration = NULL)
      values$raw_data_input <- NULL
      values$data_source_key <- "src_none"
      values$processing_error <- e$message
    })
  }, ignoreInit = FALSE)

  # Built-in device samples: the "raw device export" path demo, seeded with
  # two anonymized real exports so the Convert workflow (review ID -> Convert
  # -> preview -> Load) can be practised without real files.
  observeEvent(input$use_device_sample, {
    if (!isTRUE(input$use_device_sample)) {
      if (isTRUE(values$device_sample_active)) {
        values$device_sample_active <- FALSE
        values$raw_files_info <- list()
        values$raw_maskids <- list()
        values$converted_raw_long <- NULL
        values$converted_raw_summary <- NULL
      }
      return()
    }
    if (isTRUE(values$device_sample_active) &&
        length(values$raw_files_info) == length(DEVICE_SAMPLE_CSVS)) return()
    reset_pipeline_state()
    values$raw_data_input <- NULL
    values$uploaded_csv_raw <- NULL
    values$uploaded_csv_files <- character(0)
    values$use_builtin_active <- FALSE
    updateCheckboxInput(session, "use_builtin_data", value = FALSE)
    values$raw_files_info <- lapply(names(DEVICE_SAMPLE_CSVS), function(id) {
      list(name = paste0(id, "_24hPWA (built-in sample)"),
           cached_path = NULL, ok = TRUE, demo = TRUE,
           demo_csv_text = DEVICE_SAMPLE_CSVS[[id]],
           conv = NULL, message = NULL)
    })
    values$raw_maskids <- as.list(names(DEVICE_SAMPLE_CSVS))
    values$converted_raw_long <- NULL
    values$converted_raw_summary <- NULL
    values$device_sample_active <- TRUE
    values$data_source_key <- "src_none"
    showNotification(tr(lang(), "device_sample_loaded"), type = "message", duration = 4)
  }, ignoreInit = FALSE)

  # Prepared CSV file(s): files with different column structures are merged
  # by column name (union); missing values stay empty.
  observeEvent(input$csv_files, {
    req(input$csv_files)
    dfs <- lapply(seq_len(nrow(input$csv_files)), function(i) {
      read_csv_smart(input$csv_files$datapath[i], input$csv_files$name[i])
    })
    if (length(dfs) > 1) {
      common <- Reduce(intersect, lapply(dfs, colnames))
      if (length(common) == 0) {
        showNotification(tr(lang(), "err_csv_cols_diff"), type = "error", duration = 10)
        values$uploaded_csv_raw <- NULL
        values$uploaded_csv_files <- character(0)
        return()
      }
    }
    reset_pipeline_state()
    values$raw_data_input <- NULL
    values$uploaded_csv_raw <- bind_rows(dfs)
    values$uploaded_csv_files <- input$csv_files$name
    values$raw_files_info <- list()
    values$use_builtin_active <- FALSE
    updateCheckboxInput(session, "use_builtin_data", value = FALSE)
    values$device_sample_active <- FALSE
    updateCheckboxInput(session, "use_device_sample", value = FALSE)
    values$glucose_sample_active <- FALSE
    updateCheckboxInput(session, "use_glucose_sample", value = FALSE)
    same_cols <- length(dfs) <= 1 ||
      all(vapply(dfs, function(d) identical(colnames(d), colnames(dfs[[1]])), logical(1)))
    if (!same_cols) {
      showNotification(tr(lang(), "csv_union_note"), type = "warning", duration = 8)
    }
    showNotification(tr(lang(), "csv_files_loaded"), type = "message", duration = 4)
  })

  # Column-mapping panel (rendered after CSV upload)
  output$mapping_panel <- renderUI({
    req(values$uploaded_csv_raw)
    src_cols <- colnames(values$uploaded_csv_raw)
    detected <- alias_lookup(src_cols)
    sel_input <- function(id, label, cur) {
      choices <- setNames(src_cols, src_cols)
      choices <- c(setNames("", tr(lang(), "map_not_used")), choices)
      # `cur` may be NULL/NA/length != 1 for an unmapped or undetected target;
      # only a single non-NA name that actually exists can be preselected.
      selected <- if (length(cur) == 1L && !is.na(cur) && cur %in% src_cols) cur else ""
      selectInput(id, label, choices = choices, selected = selected, width = "100%")
    }
    wellPanel(
      h5(icon("map-signs"), tr(lang(), "mapping_title")),
      p(tr(lang(), "mapping_hint"), style = "font-size:0.85em;color:#555;"),
      sel_input("map_id", tr(lang(), "map_id"), detected$MASKID),
      sel_input("map_time", tr(lang(), "map_time"), detected$Time),
      sel_input("map_sbp", tr(lang(), "map_sbp"), detected$SBP),
      sel_input("map_dbp", tr(lang(), "map_dbp"), detected$DBP),
      sel_input("map_hr", tr(lang(), "map_hr"), detected$HR),
      sel_input("map_pp", tr(lang(), "map_pp"), detected$PP),
      sel_input("map_map", tr(lang(), "map_map"), detected$MAP),
      sel_input("map_glu", tr(lang(), "map_glu"), detected$GLU),
      actionButton("apply_mapping_btn", tr(lang(), "map_apply"), icon = icon("check"),
                   class = "btn-sm btn-primary btn-block")
    )
  })

  observeEvent(input$apply_mapping_btn, {
    req(values$uploaded_csv_raw)
    src <- values$uploaded_csv_raw
    pick <- function(v) if (is.null(v) || length(v) == 0L || v == "") NA_character_ else v
    mapping <- list(MASKID = pick(input$map_id), Time = pick(input$map_time),
                    SBP = pick(input$map_sbp), DBP = pick(input$map_dbp),
                    HR = pick(input$map_hr), PP = pick(input$map_pp),
                    MAP = pick(input$map_map), GLU = pick(input$map_glu))
    if (is.na(mapping$MASKID)) {
      showNotification(tr(lang(), "err_map_no_id"), type = "error", duration = 7); return()
    }
    if (is.na(mapping$Time)) {
      showNotification(tr(lang(), "err_map_no_time"), type = "error", duration = 7); return()
    }
    mapped_measures <- mapping[c("SBP", "DBP", "HR", "PP", "MAP", "GLU")]
    if (all(is.na(unlist(mapped_measures)))) {
      # Only ID and Time are strictly required; proceed with a warning.
      showNotification(tr(lang(), "warn_map_no_measure"), type = "warning", duration = 7)
    }
    out <- data.frame(MASKID = src[[mapping$MASKID]], Time = src[[mapping$Time]],
                      stringsAsFactors = FALSE)
    for (m in names(mapped_measures)) {
      col <- mapped_measures[[m]]
      # Only include mapped measurement columns; unmapped metrics are simply
      # absent instead of phantom all-NA columns (all-NA columns would make
      # every row look invalid downstream).
      if (!is.na(col)) out[[m]] <- src[[col]]
    }
    reset_pipeline_state()
    values$raw_data_input <- out
    values$use_builtin_active <- FALSE
    updateCheckboxInput(session, "use_builtin_data", value = FALSE)
    values$data_source_key <- "src_csv"
    showNotification(tr(lang(), "map_ok"), type = "message", duration = 4)
  })

  # Prepared glucose CSV file(s) (processed glucose path)
  observeEvent(input$glu_csv_files, {
    req(input$glu_csv_files)
    dfs <- lapply(seq_len(nrow(input$glu_csv_files)), function(i) {
      read_csv_smart(input$glu_csv_files$datapath[i], input$glu_csv_files$name[i])
    })
    if (length(dfs) > 1) {
      common <- Reduce(intersect, lapply(dfs, colnames))
      if (length(common) == 0) {
        showNotification(tr(lang(), "err_csv_cols_diff"), type = "error", duration = 10)
        values$uploaded_csv_raw <- NULL
        values$uploaded_csv_files <- character(0)
        return()
      }
    }
    reset_pipeline_state()
    values$raw_data_input <- NULL
    values$uploaded_csv_raw <- bind_rows(dfs)
    values$uploaded_csv_files <- input$glu_csv_files$name
    values$raw_files_info <- list()
    values$use_builtin_active <- FALSE
    updateCheckboxInput(session, "use_builtin_data", value = FALSE)
    values$device_sample_active <- FALSE
    updateCheckboxInput(session, "use_device_sample", value = FALSE)
    values$glucose_sample_active <- FALSE
    updateCheckboxInput(session, "use_glucose_sample", value = FALSE)
    values$glucose_sample_active <- FALSE
    updateCheckboxInput(session, "use_glucose_sample", value = FALSE)
    same_cols <- length(dfs) <= 1 ||
      all(vapply(dfs, function(d) identical(colnames(d), colnames(dfs[[1]])), logical(1)))
    if (!same_cols) {
      showNotification(tr(lang(), "csv_union_note"), type = "warning", duration = 8)
    }
    showNotification(tr(lang(), "csv_files_loaded"), type = "message", duration = 4)
  })

  # Raw glucose export file(s) (raw CGM path)
  observeEvent(input$glu_raw_files, {
    req(input$glu_raw_files)
    n <- nrow(input$glu_raw_files)
    infos <- vector("list", n)
    for (i in seq_len(n)) {
      name <- input$glu_raw_files$name[i]
      cached <- file.path(tempdir(), paste0("abpm_glu_", i, "_", basename(name)))
      tryCatch(file.copy(input$glu_raw_files$datapath[i], cached, overwrite = TRUE),
               error = function(e) NULL)
      infos[[i]] <- tryCatch({
        conv <- glu_raw_to_long(path = input$glu_raw_files$datapath[i],
                                file_label = name)
        list(name = name, cached_path = cached, ok = TRUE, demo = FALSE,
             parser = "glu", conv = conv, message = NULL)
      }, error = function(e) {
        list(name = name, cached_path = cached, ok = FALSE, demo = FALSE,
             parser = "glu", conv = NULL, message = conditionMessage(e))
      })
    }
    reset_pipeline_state()
    values$raw_data_input <- NULL
    values$uploaded_csv_raw <- NULL
    values$uploaded_csv_files <- character(0)
    values$raw_files_info <- infos
    values$raw_maskids <- lapply(infos, function(z) if (isTRUE(z$ok)) z$conv$auto_maskid else "")
    values$converted_raw_long <- NULL
    values$converted_raw_summary <- NULL
    values$use_builtin_active <- FALSE
    updateCheckboxInput(session, "use_builtin_data", value = FALSE)
    values$device_sample_active <- FALSE
    updateCheckboxInput(session, "use_device_sample", value = FALSE)
    values$glucose_sample_active <- FALSE
    updateCheckboxInput(session, "use_glucose_sample", value = FALSE)
    values$glucose_sample_active <- FALSE
    updateCheckboxInput(session, "use_glucose_sample", value = FALSE)
    failed <- infos[!vapply(infos, function(z) isTRUE(z$ok), logical(1))]
    if (length(failed) > 0) {
      showNotification(paste0(length(failed), " file(s) could not be parsed: ",
                              failed[[1]]$message %||% ""),
                       type = "error", duration = 10)
    }
    showNotification(tr(lang(), "raw_parsed"), type = "message", duration = 4)
  })

  # Built-in glucose sample: the raw-glucose path demo (14-day CGM).
  observeEvent(input$use_glucose_sample, {
    if (!isTRUE(input$use_glucose_sample)) {
      if (isTRUE(values$glucose_sample_active)) {
        values$glucose_sample_active <- FALSE
        values$raw_files_info <- list()
        values$raw_maskids <- list()
        values$converted_raw_long <- NULL
        values$converted_raw_summary <- NULL
      }
      return()
    }
    if (isTRUE(values$glucose_sample_active) && length(values$raw_files_info) == 1) return()
    reset_pipeline_state()
    values$raw_data_input <- NULL
    values$uploaded_csv_raw <- NULL
    values$uploaded_csv_files <- character(0)
    values$use_builtin_active <- FALSE
    updateCheckboxInput(session, "use_builtin_data", value = FALSE)
    values$device_sample_active <- FALSE
    updateCheckboxInput(session, "use_device_sample", value = FALSE)
    values$raw_files_info <- list(list(
      name = "LT2503SGHM_14d_CGM (built-in glucose sample)",
      cached_path = NULL, ok = TRUE, demo = TRUE, parser = "glu",
      demo_csv_text = GLUCOSE_SAMPLE_RAW, conv = NULL, message = NULL))
    values$raw_maskids <- list("LT2503SGHM")
    values$converted_raw_long <- NULL
    values$converted_raw_summary <- NULL
    values$glucose_sample_active <- TRUE
    values$data_source_key <- "src_none"
    showNotification(tr(lang(), "glucose_sample_loaded"), type = "message", duration = 4)
  }, ignoreInit = FALSE)
  observeEvent(input$raw_files, {
    req(input$raw_files)
    n <- nrow(input$raw_files)
    infos <- vector("list", n)
    for (i in seq_len(n)) {
      name <- input$raw_files$name[i]
      cached <- file.path(tempdir(), paste0("abpm_raw_", i, "_", basename(name)))
      tryCatch(file.copy(input$raw_files$datapath[i], cached, overwrite = TRUE),
               error = function(e) NULL)
      infos[[i]] <- tryCatch({
        conv <- xls_to_abpm_long(input$raw_files$datapath[i], maskid_override = NULL,
                                 file_label = input$raw_files$name[i])
        list(name = name, cached_path = cached, ok = TRUE, conv = conv, message = NULL)
      }, error = function(e) {
        list(name = name, cached_path = cached, ok = FALSE, conv = NULL, message = conditionMessage(e))
      })
    }
    reset_pipeline_state()
    values$raw_data_input <- NULL
    values$uploaded_csv_raw <- NULL
    values$uploaded_csv_files <- character(0)
    values$raw_files_info <- infos
    values$raw_maskids <- lapply(infos, function(z) if (isTRUE(z$ok)) z$conv$auto_maskid else "")
    values$converted_raw_long <- NULL
    values$converted_raw_summary <- NULL
    values$use_builtin_active <- FALSE
    updateCheckboxInput(session, "use_builtin_data", value = FALSE)
    values$device_sample_active <- FALSE
    updateCheckboxInput(session, "use_device_sample", value = FALSE)
    values$glucose_sample_active <- FALSE
    updateCheckboxInput(session, "use_glucose_sample", value = FALSE)
    failed <- infos[!vapply(infos, function(z) isTRUE(z$ok), logical(1))]
    if (length(failed) > 0) {
      first_msg <- failed[[1]]$message %||% ""
      showNotification(
        paste0(length(failed), " file(s) could not be parsed: ", first_msg),
        type = "error", duration = 10)
    }
    showNotification(tr(lang(), "raw_parsed"), type = "message", duration = 4)
  })

  # NOTE: edited per-file MASKIDs are read at Convert-click time only. A
  # generic "persist on every input change" observer is deliberately NOT used
  # here: it races with the sample-seeding observers and could write a stale
  # previous sample's ID back over the freshly seeded one (wrong-ID risk).
  # Consequently, edits are reset if the page is re-rendered (language switch)
  # before Convert is clicked.

  output$raw_convert_panel <- renderUI({
    infos <- values$raw_files_info
    req(length(infos) > 0)
    maskid_inputs <- lapply(seq_along(infos), function(i) {
      textInput(paste0("raw_maskid_", i),
                label = paste0(basename(infos[[i]]$name), " — ", tr(lang(), "raw_maskid_label")),
                value = values$raw_maskids[[i]] %||% "")
    })
    wellPanel(
      h5(icon("file-import"), tr(lang(), "raw_panel_title")),
      p(tr(lang(), "raw_hint"), style = "font-size:0.85em;color:#555;"),
      do.call(tagList, maskid_inputs),
      fluidRow(
        column(6, actionButton("convert_raw_btn", tr(lang(), "raw_convert_btn"),
                               icon = icon("cogs"), class = "btn-sm btn-info btn-block")),
        column(6, actionButton("load_converted_btn", tr(lang(), "raw_load_btn"),
                               icon = icon("check"), class = "btn-sm btn-primary btn-block"))
      ),
      downloadButton("download_converted_csv", tr(lang(), "raw_download_btn"),
                     class = "btn-sm btn-success btn-block", style = "margin-top:8px;")
    )
  })

  observeEvent(input$convert_raw_btn, {
    infos <- values$raw_files_info
    req(length(infos) > 0)
    parts <- vector("list", length(infos))
    summary_rows <- list()
    for (i in seq_along(infos)) {
      info <- infos[[i]]
      if (!isTRUE(info$ok)) {
        summary_rows[[i]] <- data.frame(
          File = info$name, MASKID = NA_character_, Start = NA_character_,
          Total = 0, Valid = 0, Dropped_zero = 0, Dropped_bad_time = 0,
          Error = info$message %||% "", stringsAsFactors = FALSE)
        next
      }
      values$raw_maskids[[i]] <- input[[paste0("raw_maskid_", i)]] %||% ""
      conv <- if (isTRUE(info$demo) && identical(info$parser, "glu")) {
        # built-in glucose sample: parse the embedded raw-layout text
        tryCatch(glu_raw_to_long(text = info$demo_csv_text,
                                 maskid_override = values$raw_maskids[[i]],
                                 file_label = info$name),
                 error = function(e) e)
      } else if (isTRUE(info$demo)) {
        # built-in device sample: the CSV is already in canonical form;
        # apply the (possibly edited) MASKID and fake the conversion report
        demo_csv <- read.csv(text = info$demo_csv_text, stringsAsFactors = FALSE,
                             check.names = FALSE)
        new_id <- trimws(as.character(values$raw_maskids[[i]]))
        if (nzchar(new_id)) demo_csv$MASKID <- as.character(new_id)
        list(
          data = demo_csv,
          meta = list(),
          sheet = NA_character_,
          n_total = nrow(demo_csv),
          n_valid = nrow(demo_csv),
          n_dropped_zero = 0,
          n_dropped_bad_time = 0,
          first_valid = if (nrow(demo_csv) > 0) as.character(demo_csv$Time[1]) else NA_character_,
          last_valid = if (nrow(demo_csv) > 0) as.character(demo_csv$Time[nrow(demo_csv)]) else NA_character_,
          auto_maskid = if (nrow(demo_csv) > 0) as.character(demo_csv$MASKID[1]) else NA_character_
        )
      } else if (identical(info$parser, "glu")) {
        tryCatch(glu_raw_to_long(path = info$cached_path,
                                 maskid_override = values$raw_maskids[[i]],
                                 file_label = info$name),
                 error = function(e) e)
      } else {
        tryCatch(xls_to_abpm_long(info$cached_path,
                                  maskid_override = values$raw_maskids[[i]],
                                  file_label = info$name),
                 error = function(e) e)
      }
      if (inherits(conv, "error")) {
        summary_rows[[i]] <- data.frame(
          File = info$name, MASKID = NA_character_, Start = NA_character_,
          Total = 0, Valid = 0, Dropped_zero = 0, Dropped_bad_time = 0,
          Error = conditionMessage(conv), stringsAsFactors = FALSE)
        next
      }
      parts[[i]] <- conv$data
      summary_rows[[i]] <- data.frame(
        File = info$name,
        MASKID = if (nrow(conv$data) > 0) conv$data$MASKID[1] else conv$auto_maskid,
        Start = conv$first_valid,
        Total = conv$n_total,
        Valid = conv$n_valid,
        Dropped_zero = conv$n_dropped_zero,
        Dropped_bad_time = conv$n_dropped_bad_time,
        Error = "", stringsAsFactors = FALSE)
    }
    parts_ok <- parts[!vapply(parts, is.null, logical(1))]
    merged <- if (length(parts_ok) > 0) bind_rows(parts_ok) else NULL
    values$converted_raw_long <- if (!is.null(merged) && nrow(merged) > 0) merged else NULL
    values$converted_raw_summary <- bind_rows(summary_rows)
    if (is.null(values$converted_raw_long)) {
      err_msgs <- unique(c(
        vapply(infos, function(z) if (isTRUE(z$ok)) "" else z$message %||% "", character(1)),
        as.character(values$converted_raw_summary$Error)
      ))
      err_msgs <- unique(err_msgs[nzchar(err_msgs)])
      if (length(err_msgs) > 0) {
        showNotification(err_msgs[1], type = "error", duration = 10)
      } else {
        showNotification(tr(lang(), "err_no_valid_readings"), type = "error", duration = 7)
      }
    } else {
      showNotification(tr(lang(), "raw_converted_ok"), type = "message", duration = 5)
    }
  })

  observeEvent(input$load_converted_btn, {
    req(values$converted_raw_long)
    reset_pipeline_state()
    values$raw_data_input <- values$converted_raw_long
    values$use_builtin_active <- FALSE
    updateCheckboxInput(session, "use_builtin_data", value = FALSE)
    values$data_source_key <- "src_raw"
    showNotification(tr(lang(), "raw_loaded"), type = "message", duration = 4)
  })

  output$download_converted_csv <- downloadHandler(
    filename = function() paste0("ABPM_preprocessed_", Sys.Date(), ".csv"),
    content = function(file) {
      req(values$converted_raw_long)
      con <- base::file(file, open = "wb")
      on.exit(close(con), add = TRUE)
      writeBin(as.raw(c(0xEF, 0xBB, 0xBF)), con)
      write.table(values$converted_raw_long, con, sep = ",", row.names = FALSE,
                  col.names = TRUE, qmethod = "double", na = "")
    }
  )

  # --- Input tab outputs ---
  output$data_source_title <- renderText({
    paste(tr(lang(), "data_preview_title"), "(", tr(lang(), values$data_source_key), ")")
  })

  output$data_status_line <- renderUI({
    items <- list()
    if (length(values$uploaded_csv_files) > 0) {
      items[[length(items) + 1]] <- tags$li(tr(lang(), "status_csv_files"), ": ",
                                            paste(values$uploaded_csv_files, collapse = ", "))
    }
    if (length(values$raw_files_info) > 0) {
      names_raw <- vapply(values$raw_files_info, function(z) z$name, character(1))
      items[[length(items) + 1]] <- tags$li(tr(lang(), "status_raw_files"), ": ",
                                            paste(names_raw, collapse = ", "))
    }
    if (!is.null(values$raw_data_input)) {
      items[[length(items) + 1]] <- tags$li(tr(lang(), "status_working_rows"), ": ",
                                            nrow(values$raw_data_input))
    }
    if (length(items) == 0) return(NULL)
    tags$ul(style = "font-size:0.85em;color:#555;", do.call(tagList, items))
  })

  output$raw_data_table <- renderDT({
    req(values$raw_data_input)
    datatable(head(values$raw_data_input, 200),
              caption = tr(lang(), "caption_raw"),
              options = list(scrollX = TRUE, pageLength = 5, lengthMenu = c(5, 10, 20)),
              rownames = FALSE)
  })

  output$raw_convert_summary <- renderDT({
    req(values$converted_raw_summary)
    datatable(values$converted_raw_summary, caption = tr(lang(), "raw_summary_title"),
              options = list(scrollX = TRUE, pageLength = 5, dom = "t"),
              rownames = FALSE)
  })

  output$raw_convert_preview <- renderDT({
    req(values$converted_raw_long)
    datatable(head(values$converted_raw_long, 200), caption = tr(lang(), "raw_preview_title"),
              options = list(scrollX = TRUE, pageLength = 5, lengthMenu = c(5, 10, 20)),
              rownames = FALSE)
  })

  output$field_defs_table <- renderDT({
    datatable(FIELD_DEFS, caption = tr(lang(), "field_defs_title"),
              options = list(scrollX = TRUE, pageLength = 15, searchDelay = 500),
              rownames = FALSE, filter = "top")
  })

  output$guide_metric_defs_table <- renderDT({
    datatable(METRIC_DEFS, options = list(scrollX = TRUE, pageLength = 12, dom = "t"),
              rownames = FALSE)
  })

  # --- UI Rendering for Data Tables (Unchanged) ---
  output$prepared_long_table <- renderDT({ req(values$prepared_long_data); datatable(values$prepared_long_data, caption = chart_tr("caption_prepared"), options = list(scrollX = TRUE, pageLength = 10), rownames = FALSE, filter='top') })
  output$wide_data_tabs <- renderUI({
    req(values$data_processed_successfully, length(values$wide_dfs) > 0)
    metrics_available <- names(values$wide_dfs)
    if (length(metrics_available) == 0) return(p(chart_tr("no_wide_data")))
    metric_tabs <- lapply(metrics_available, function(metric) { tabPanel(title = metric, DTOutput(paste0("wide_", tolower(metric), "_table"))) })
