  output$variability_chart_24h_segmented <- renderPlotly({
    data <- viz_data_reactive(); req(data, !is.null(data$results_24h_segmented), ncol(data$results_24h_segmented) > 1)
    ref_vals <- VARIABILITY_REFERENCE_VALUES[[data$metric_id]]
    # Note: SD/ARV for segmented 24h are calculated on the *full* 24h data in calculate_abpm_metrics_24h_segmented
    p <- create_variability_chart(data$results_24h_segmented, data$patient_id, data$metric_id,
                                  sd_reference = ref_vals$sd, arv_reference = ref_vals$arv)
    p %>% layout(title = NULL)
  })
  
  
  # --- Assign Renderers for VIZ TAB - Day ---
  output$viz_info_day <- render_viz_info_ui("day")
  output$patient_summary_day <- render_patient_summary_print("day")
  output$bp_trend_chart_day <- renderPlotly({ # Show the segmented chart here as well
    data <- viz_data_reactive(); req(data)
    metric_lc <- tolower(data$metric_id)
    targets_day <- data$targets_day; targets_night <- data$targets_night
    day_l <- targets_day[[paste0(metric_lc, "_day_lower")]]; day_u <- targets_day[[paste0(metric_lc, "_day_upper")]]
    night_l <- targets_night[[paste0(metric_lc, "_night_lower")]]; night_u <- targets_night[[paste0(metric_lc, "_night_upper")]]
    p <- create_metric_trend_chart_24h(
      bp_data = data$interpolated_data, sorted_times = data$sorted_times, sorted_minutes = data$sorted_minutes,
      maskid_selected = data$patient_id, metric_name = data$metric_id,
      day_upper_limit = day_u, day_lower_limit = day_l,
      night_upper_limit = night_u, night_lower_limit = night_l,
      day_start1_h = isolate(input$day1_start_h), day_start1_m = isolate(input$day1_start_m),
      night_start1_h = isolate(input$day1_night_start_h), night_start1_m = isolate(input$day1_night_start_m),
      day_start2_h = isolate(input$day2_start_h), day_start2_m = isolate(input$day2_start_m),
      night_start2_h = isolate(input$day2_night_start_h), night_start2_m = isolate(input$day2_night_start_m)
    )
    p %>% layout(title = NULL)
  })
  output$time_in_range_donut_day <- renderPlotly({
    data <- viz_data_reactive(); req(data, !is.null(data$results_day), ncol(data$results_day) > 1)
    p <- create_time_in_range_donut(data$results_day, data$patient_id, data$metric_id)
    p %>% layout(title = NULL)
  })
  output$burden_chart_day <- renderPlotly({
    data <- viz_data_reactive(); req(data, !is.null(data$results_day), ncol(data$results_day) > 1)
    p <- create_burden_chart(data$results_day, data$patient_id, data$metric_id)
    p %>% layout(title = NULL)
  })
  output$variability_chart_day <- renderPlotly({
    data <- viz_data_reactive(); req(data, !is.null(data$results_day), ncol(data$results_day) > 1)
    ref_vals <- VARIABILITY_REFERENCE_VALUES[[data$metric_id]]
    p <- create_variability_chart(data$results_day, data$patient_id, data$metric_id,
                                  sd_reference = ref_vals$sd, arv_reference = ref_vals$arv)
    p %>% layout(title = NULL)
  })
  
  # --- Assign Renderers for VIZ TAB - Night ---
  output$viz_info_night <- render_viz_info_ui("night")
  output$patient_summary_night <- render_patient_summary_print("night")
  output$bp_trend_chart_night <- renderPlotly({ # Show the segmented chart here as well
    data <- viz_data_reactive(); req(data)
    metric_lc <- tolower(data$metric_id)
    targets_day <- data$targets_day; targets_night <- data$targets_night
    day_l <- targets_day[[paste0(metric_lc, "_day_lower")]]; day_u <- targets_day[[paste0(metric_lc, "_day_upper")]]
    night_l <- targets_night[[paste0(metric_lc, "_night_lower")]]; night_u <- targets_night[[paste0(metric_lc, "_night_upper")]]
    p <- create_metric_trend_chart_24h(
      bp_data = data$interpolated_data, sorted_times = data$sorted_times, sorted_minutes = data$sorted_minutes,
      maskid_selected = data$patient_id, metric_name = data$metric_id,
      day_upper_limit = day_u, day_lower_limit = day_l,
      night_upper_limit = night_u, night_lower_limit = night_l,
      day_start1_h = isolate(input$day1_start_h), day_start1_m = isolate(input$day1_start_m),
      night_start1_h = isolate(input$day1_night_start_h), night_start1_m = isolate(input$day1_night_start_m),
      day_start2_h = isolate(input$day2_start_h), day_start2_m = isolate(input$day2_start_m),
      night_start2_h = isolate(input$day2_night_start_h), night_start2_m = isolate(input$day2_night_start_m)
    )
    p %>% layout(title = NULL)
  })
  output$time_in_range_donut_night <- renderPlotly({
    data <- viz_data_reactive(); req(data, !is.null(data$results_night), ncol(data$results_night) > 1)
    p <- create_time_in_range_donut(data$results_night, data$patient_id, data$metric_id)
    p %>% layout(title = NULL)
  })
  output$burden_chart_night <- renderPlotly({
    data <- viz_data_reactive(); req(data, !is.null(data$results_night), ncol(data$results_night) > 1)
    p <- create_burden_chart(data$results_night, data$patient_id, data$metric_id)
    p %>% layout(title = NULL)
  })
  output$variability_chart_night <- renderPlotly({
    data <- viz_data_reactive(); req(data, !is.null(data$results_night), ncol(data$results_night) > 1)
    ref_vals <- VARIABILITY_REFERENCE_VALUES[[data$metric_id]]
    p <- create_variability_chart(data$results_night, data$patient_id, data$metric_id,
                                  sd_reference = ref_vals$sd, arv_reference = ref_vals$arv)
    p %>% layout(title = NULL)
  })
  
  

  # --- Glucose target presets: normal range / diabetes management range ---
  apply_glu_preset <- function(lo, hi, msg_key) {
    for (p in c("day", "night", "24h")) {
      updateNumericInput(session, paste0("glu_", p, "_lower"), value = lo)
      updateNumericInput(session, paste0("glu_", p, "_upper"), value = hi)
    }
    showNotification(tr(lang(), msg_key), type = "message", duration = 5)
  }
  observeEvent(input$preset_glu_normal, {
    if (isTRUE(values$targets_locked)) {
      showNotification(chart_tr("locked_warn"), type = "warning", duration = 5)
      return()
    }
    apply_glu_preset(3.9, 7.8, "glu_preset_normal_msg")
  }, ignoreInit = TRUE)
  observeEvent(input$preset_glu_diabetes, {
    if (isTRUE(values$targets_locked)) {
      showNotification(chart_tr("locked_warn"), type = "warning", duration = 5)
      return()
    }
    apply_glu_preset(3.9, 10.0, "glu_preset_diabetes_msg")
  }, ignoreInit = TRUE)

  # --- Glucose (CGM) personalized analysis block ---
  has_glu_results <- reactive({
    isTRUE(values$metrics_calculated_successfully) &&
      !is.null(values$metric_results$`24h`$GLU) &&
      is.data.frame(values$metric_results$`24h`$GLU) &&
      nrow(values$metric_results$`24h`$GLU) > 0
  })

  output$personal_glu_block <- renderUI({
    req(has_glu_results())
    tagList(
      h4(icon("notes-medical"), tr(lang(), "glu_followup_title")),
      uiOutput("glu_personal_followup_level"),
      h4(icon("project-diagram"), tr(lang(), "glu_dims_title")),
      DTOutput("glu_personal_dimension_table"),
      br(),
      h4(icon("book-medical"), tr(lang(), "glu_guidelines_title")),
      DTOutput("glu_personal_guideline_table"),
      p(style = "font-size:0.85em;color:#666;", tr(lang(), "glu_note")),
      br(),
      h4(icon("comment-medical"), tr(lang(), "advice_title")),
      uiOutput("glu_personal_advice")
    )
  })

  glu_assessment_reactive <- reactive({
    req(has_glu_results(), input$analysis_maskid)
    build_glucose_assessment(values$metric_results, input$analysis_maskid, lang = lang())
  })

  output$glu_personal_followup_level <- renderUI({
    assessment <- glu_assessment_reactive()
    colour <- switch(assessment$followup_key,
                     "urgent" = "#c62828",
                     "elective" = "#ef6c00",
                     "routine" = "#2e7d32",
                     "#333333")
    tagList(
      h3(style = paste0("color:", colour, ";margin-top:5px;"), icon("stethoscope"), assessment$followup),
      p(chart_tr("followup_note"))
    )
  })

  output$glu_personal_dimension_table <- renderDT({
    assessment <- glu_assessment_reactive()
    datatable(assessment$dimensions, rownames = FALSE, escape = FALSE,
              options = list(dom = "t", paging = FALSE, searching = FALSE,
                             ordering = FALSE, scrollX = TRUE))
  })

  output$glu_personal_guideline_table <- renderDT({
    assessment <- glu_assessment_reactive()
    datatable(assessment$guidelines, rownames = FALSE,
              options = list(dom = "t", paging = FALSE, searching = FALSE,
                             ordering = FALSE, scrollX = TRUE))
  })

  output$glu_personal_advice <- renderUI({
    assessment <- glu_assessment_reactive()
    wellPanel(
      tags$ul(lapply(assessment$suggestions, tags$li)),
      p(style = "font-size:0.85em;color:#666;margin-bottom:0;",
        chart_tr("advice_note"))
    )
  })

  # --- Selected-item exports (tick boxes in the sidebar) ---
  export_period_results <- function() {
    out <- list()
    period_prefix <- c(day = "day", night = "night", `24h` = "24h_unified",
                       `24h_segmented` = "24h_segmented")
    for (pk in names(period_prefix)) {
      for (metric in names(values$metric_results[[pk]])) {
        df <- values$metric_results[[pk]][[metric]]
        if (!is.null(df) && is.data.frame(df) && nrow(df) > 0) {
          out[[paste0(period_prefix[[pk]], "_", metric)]] <- df
        }
      }
    }
    out
  }

  export_split_tables <- function() {
    out <- list()
    for (pname in names(values$split_data_wide)) {
      if (is.null(values$split_data_wide[[pname]])) next
      for (metric in names(values$split_data_wide[[pname]])) {
        df <- values$split_data_wide[[pname]][[metric]]
        if (!is.null(df) && is.data.frame(df) && nrow(df) > 0) {
          out[[paste0("split_", pname, "_", metric)]] <- df
        }
      }
    }
    out
  }

  export_interp_tables <- function() {
    out <- list()
    for (metric in names(values$interpolated_dfs)) {
      df <- values$interpolated_dfs[[metric]]
      if (!is.null(df) && is.data.frame(df) && nrow(df) > 0) {
        out[[paste0("interp_", metric)]] <- df
      }
    }
    out
  }

  # Each selected item is a list(id, csv = named list, xlsx = named list).
  export_items_reactive <- function() {
    sel <- input$export_items
    if (is.null(sel) || length(sel) == 0) return(list())
    items <- list()
    if ("wide" %in% sel) {
      items[["wide"]] <- list(
        csv = list(full_wide_table = full_export_reactive()),
        xlsx = list(`Full Wide Table` = full_export_reactive()))
    }
    if ("period" %in% sel) {
      p <- export_period_results()
      if (length(p) > 0) items[["period"]] <- list(csv = p, xlsx = p)
    }
    if ("personal" %in% sel) {
      a <- build_all_personalized_assessments(values$metric_results, lang = lang())
      if (nrow(a) > 0) {
        items[["personal"]] <- list(csv = list(personalized_analysis = a),
                                    xlsx = list(`Personalized Analysis` = a))
      }
    }
    if ("prepared" %in% sel && !is.null(values$prepared_long_data)) {
      items[["prepared"]] <- list(csv = list(prepared_long_data = values$prepared_long_data),
                                  xlsx = list(`Prepared Long Data` = values$prepared_long_data))
    }
    if ("interp" %in% sel) {
      p <- export_interp_tables()
      if (length(p) > 0) items[["interp"]] <- list(csv = p, xlsx = p)
    }
    if ("split" %in% sel) {
      p <- export_split_tables()
      if (length(p) > 0) items[["split"]] <- list(csv = p, xlsx = p)
    }
    items
  }

  output$download_sel_csv <- downloadHandler(
    filename = function() paste0("ABPM_selected_results_", Sys.Date(), ".zip"),
    content = function(file) {
      items <- export_items_reactive()
      packed <- length(items) > 0 && isTRUE(write_export_zip(items, file))
      if (!packed) {
        showNotification(tr(lang(), "export_empty_warn"), type = "warning", duration = 5)
        return(invisible(NULL))
      }
    },
    contentType = "application/zip"
  )

  output$download_sel_xlsx <- downloadHandler(
    filename = function() paste0("ABPM_selected_results_", Sys.Date(), ".xlsx"),
    content = function(file) {
      items <- export_items_reactive()
      if (length(items) == 0) {
        showNotification(tr(lang(), "export_empty_warn"), type = "warning", duration = 5)
        return(NULL)
      }
      sheets <- unlist(lapply(items, function(it) it$xlsx), recursive = FALSE)
      sheet_names <- substr(vapply(names(sheets), sanitize_filename, character(1)), 1, 31)
      # de-duplicate sheet names defensively
      if (any(duplicated(sheet_names))) {
        sheet_names <- make.unique(sheet_names, sep = "_")
        sheet_names <- substr(sheet_names, 1, 31)
      }
      names(sheets) <- sheet_names
      openxlsx::write.xlsx(sheets, file = file, overwrite = TRUE, asTable = TRUE)
    }
  )

} # End server function

# --- 5. Static UI shell: persistent header (language switch / tour) + page ---
# Everything else is rendered by output$page (build_ui) so that the interface
# language can be switched without reloading the app.
ui <- fluidPage(
  theme = shinytheme("flatly"),
  shinyjs::useShinyjs(),
  if (has_introjs) rintrojs::introjsUI() else NULL,

  tags$head(
    tags$style(HTML("
      .well h5 { margin-top: 0; margin-bottom: 10px; font-weight: bold; }
      .summary-well { background-color: #f0f9ff; border: 1px solid #b3e0ff; border-radius: 5px; padding: 10px 15px; min-height: 130px; }
      .stats-well { background-color: #f8f9fa; border-radius: 5px; padding: 10px 15px; min-height: 130px; }
      .plot-well { background-color: #ffffff; border: 1px solid #ddd; border-radius: 5px; padding: 5px; margin-bottom: 15px; }
      .plot-well-header { padding: 8px 15px; background-color: #f5f5f5; border-bottom: 1px solid #ddd; border-radius: 5px 5px 0 0; font-weight: bold; color: #337ab7; }
      .plot-well-body { padding: 15px; }
      .app-header { display: flex; align-items: center; justify-content: space-between;
                    flex-wrap: wrap; background-color: #ffffff; border-bottom: 1px solid #e5e5e5;
                    padding: 10px 20px; margin-bottom: 10px; }
      .app-header .app-title { font-size: 1.5em; font-weight: bold; color: #2c3e50; }
      .app-header .app-tools { display: flex; align-items: center; gap: 10px; }
      .app-header .app-tools .radio-inline { margin-bottom: 0; }
      footer { text-align: center; padding: 15px; background-color: #f5f5f5;
               margin-top: 30px; border-top: 1px solid #ddd; font-size: 0.9em; color: #555; }
    "))
  ),

  div(class = "app-header",
      div(class = "app-title", uiOutput("header_title")),
      div(class = "app-tools",
          radioButtons("lang_radio", NULL,
                       choices = c("English" = "en", "中文" = "zh"),
                       selected = "en", inline = TRUE),
          actionButton("tour_btn", NULL, icon = icon("map-signs"),
                       class = "btn-sm btn-info",
                       title = "Start guided tour / 开始引导"))
  ),

  uiOutput("page"),

  tags$footer(uiOutput("footer_text"))
)

# --- 6. Run the Application ---
shinyApp(ui = ui, server = server)
